INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C1','math',2,2,'u2',2,'2단 곱셈구구 — 한 묶음이 2씩 늘어나는 상황을 곱셈식으로 나타내고, 2 × 5를 2씩 5번 더하기와 2 × 4에 2 더하기로 구하며, 곱하는 수가 1 커지면 곱이 2씩 커짐을 알기',ARRAY['2수01-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C2','math',2,2,'u2',3,'5단 곱셈구구 — 5씩 커지는 원리로 5단을 완성하고, 곱의 일의 자리 숫자가 5, 0으로 되풀이되는 규칙을 찾기',ARRAY['2수01-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C3','math',2,2,'u2',4,'3단·6단 곱셈구구 — 3씩·6씩 커지는 원리로 3단과 6단을 완성하고, 6 × 5를 5 × 6처럼 다르게 묶어 구하며, 6단의 곱이 3단의 곱의 2배임을 알기',ARRAY['2수01-10']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C4','math',2,2,'u2',5,'4단·8단 곱셈구구 — 4씩·8씩 커지는 원리로 4단과 8단을 완성하고, 8 × 6을 8 × 3 두 번 더하기 등 여러 방법으로 구하며, 8단의 곱이 4단의 곱의 2배임을 알기',ARRAY['2수01-10']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C5','math',2,2,'u2',6,'7단 곱셈구구 — 수직선에서 7씩 뛰어 세고, 7 × 5를 7 × 3과 7 × 2로 나누어 구하며, 7 × 6을 7 × 5에 7 더하기와 6 × 7로 구해 7단을 완성하기',ARRAY['2수01-10']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C6','math',2,2,'u2',7,'9단 곱셈구구 — 9씩 커지는 원리로 9단을 완성하고, 9 × 5를 9 × 2와 9 × 3의 곱을 더해 구하며, 곱의 두 숫자의 합이 9인 규칙을 찾기',ARRAY['2수01-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C7','math',2,2,'u2',8,'1단 곱셈구구와 0의 곱 — 1과 어떤 수의 곱은 그 수, 0과 어떤 수의 곱과 어떤 수와 0의 곱은 0임을 알고 점수 상황에 쓰기',ARRAY['2수01-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C8','math',2,2,'u2',9,'곱셈표 — 가로줄과 세로줄의 수가 만나는 칸에 곱을 써서 곱셈표를 만들고, 단마다 곱이 그 단의 수만큼 커지는 원리로 빈칸을 채우며, 두 수를 바꾸어 곱해도 곱이 같고 곱이 같은 곱셈구구가 여럿일 수 있음을 알기',ARRAY['2수01-10']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C9','math',2,2,'u2',10,'곱셈구구로 문제 해결하기 — 생활 속 물건의 수를 곱셈구구로 구하고, 빈자리가 있거나 두 덩이로 된 배열은 나누어 곱한 뒤 더하거나 빼서 구하기',ARRAY['2수01-10']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-2-u2-C10','math',2,2,'u2',12,'곱셈구구 속 규칙 찾기 — 곱의 일의 자리 숫자를 차례로 이어 단마다 생기는 무늬를 찾고, 다른 단인데 같은 무늬가 나오는 까닭을 말하기',ARRAY['2수01-10']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X01','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6']::text[],'곱하는 수가 1 커지면 곱도 1 커진다고 여긴다(2 × 5를 2 × 4보다 1 크다고 봄)','곱하는 수가 1 커지면 그 단의 수를 한 번 더 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X02','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C8']::text[],'곱셈구구의 곱을 이웃 곱(한 번 더·덜 뛴 값)과 헷갈리거나 뛰어 세기를 한 번 더·덜 한다','뛸 때마다 손가락을 하나씩 접어 곱하는 수만큼 뛰었는지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X03','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'그림에서 묶음이나 줄의 수를 하나 더·덜 센다','묶음·줄마다 번호를 붙이며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X04','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'「몇씩」(한 묶음·한 줄의 수)과 「몇 묶음·몇 줄」을 뒤바꾸어 곱셈식을 쓴다','× 앞에는 한 묶음의 수, 뒤에는 묶음의 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X05','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C7','M2-2-u2-C9']::text[],'묻는 것 대신 곱하는 수·묶음 수·맞힌 횟수 같은 다른 수를 답으로 쓴다','물음이 「모두 몇」인지 「몇 번·몇 묶음」인지 밑줄 긋기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X06','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C7','M2-2-u2-C9']::text[],'곱셈구구를 두 수를 더하거나 빼서 구한다(2 × 5 = 7)','두 수를 더하지 말고 앞의 수를 뒤의 수만큼 여러 번 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X08','math',2,'u2',ARRAY['M2-2-u2-C7']::text[],'0이나 1을 곱할 때 0의 곱을 그 수로(3 × 0 = 3), 1의 곱을 1로(1 × 5 = 1) 여기거나, 한 번도 못 맞힌 점수를 그 점수로 센다','0번 더하면 아무것도 없어 0, 1을 몇 번 더하면 그 횟수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X09','math',2,'u2',ARRAY['M2-2-u2-C8']::text[],'곱셈표에서 가로줄·세로줄을 잘못 짚어 이웃 칸을 읽거나 줄과 칸을 뒤바꾼다','왼쪽 수와 위쪽 수를 손가락 두 개로 짚어 만나는 칸 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X10','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C4']::text[],'단과 단 사이의 관계를 모른다 — 6단을 3단과, 8단을 4단과 따로 외우거나, 같은 수를 곱할 때 6단의 곱이 3단의 곱의 2배임을 모른다','3씩 2묶음이 6, 4씩 2묶음이 8 — 묶음을 두 개씩 합쳐 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X11','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C9']::text[],'× 를 + 로 여기거나 곱셈식을 잘못 읽는다','× 는 「곱하기」 — 앞의 수를 뒤의 수만큼 여러 번 더한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X13','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C5','M2-2-u2-C7','M2-2-u2-C8']::text[],'두 수를 바꾸어 곱해도 곱이 같다는 것을 모르거나, 곱이 같은 곱셈구구를 하나만 찾는다(24 = 3 × 8 = 4 × 6을 놓침)','곱셈표를 점선을 따라 접어 만나는 칸, 같은 곱이 나오는 다른 단 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X14','math',2,'u2',ARRAY['M2-2-u2-C9']::text[],'생활 속 상황에서 한 묶음의 수와 묶음의 수를 잘못 잡는다(다리 수와 마리 수를 헷갈림)','「한 ○에 몇 개씩」이 한 묶음, 「○가 몇」이 묶음 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X15','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C7','M2-2-u2-C8','M2-2-u2-C9','M2-2-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못된↔바른','물음의 「아닌·잘못된」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X16','math',2,'u2',ARRAY['M2-2-u2-C2','M2-2-u2-C6','M2-2-u2-C8','M2-2-u2-C10']::text[],'곱의 규칙(5단 일의 자리 5·0, 9단 두 숫자의 합 9, 일의 자리 무늬)을 곱하는 수의 규칙과 헷갈리거나 곱 전체를 이어 잘못 찾는다','곱을 차례로 쓰고 일의 자리·십의 자리 숫자에 따로 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X17','math',2,'u2',ARRAY['M2-2-u2-C1','M2-2-u2-C2','M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C9']::text[],'한 번 더 더하기·나누어 구하기에서 곱하는 수를 더하거나(2 × 4 + 5) 두 곱 대신 두 수만 더한다(9 × 2와 9 × 3에서 2 + 3)','한 번 더 더할 때는 그 단의 수를, 나누어 구할 때는 두 곱을 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X18','math',2,'u2',ARRAY['M2-2-u2-C9']::text[],'줄 맞춰 놓이지 않은 배열(빈자리·두 덩이·낱개)에서 빈자리를 빼지 않거나 한 덩이·낱개를 빠뜨린다','빈자리에 ×, 덩이마다 색을 다르게 칠하고 따로 구하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-2-u2-X19','math',2,'u2',ARRAY['M2-2-u2-C3','M2-2-u2-C4','M2-2-u2-C5','M2-2-u2-C6','M2-2-u2-C8','M2-2-u2-C9']::text[],'곱을 구하지 않고 앞의 수나 한 수만 보고 두 곱셈식의 크기를 견준다','두 곱셈식의 곱을 먼저 구해 옆에 쓰고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#1','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'mc','auto','그림을 보세요. 쿠키는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 쿠키는 모두 몇 개인가요?","explanation":["2개씩 4묶음이에요.","2씩 뛰어 세면 2, 4, 6, 8.","쿠키는 모두 8개예요."],"variant_rule":{"mul":{"ask":"total","ks":[2],"pmax":45}},"options":[{"t":"8개","correct":true},{"t":"6개","mis":"M2-2-u2-X06"},{"t":"4개","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"🍪","k":2,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#2','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","8에서 2만큼 더 뛰면 10이에요.","2씩 5번 뛰어 센 수 — 2씩 5묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["10"],"asset":{"type":"jump_row","cells":[2,4,6,8,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#3','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'mc','auto','로봇 한 대에 바퀴가 2개씩 있어요. 로봇이 한 대 더 늘어나면 바퀴는 몇 개 더 많아지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],true,'{"seq":3,"concept":"M2-2-u2-C1","difficulty":1,"kind":"mc","stem":"로봇 한 대에 바퀴가 2개씩 있어요. 로봇이 한 대 더 늘어나면 바퀴는 몇 개 더 많아지나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"M2-2-u2-X01"},{"t":"4개","mis":"M2-2-u2-X02"}],"explanation":["로봇 한 대에 바퀴가 2개씩이에요.","로봇이 한 대 늘면 바퀴 2개가 더 생겨요.","그래서 2단 곱셈구구의 곱은 2씩 커져요."],"variant_rule":{"alt":[{"stem":"필통 한 개에 지우개가 2개씩 들어 있어요. 필통이 하나 더 늘어나면 지우개는 몇 개 더 많아지나요?","options":[{"t":"2개","correct":true},{"t":"1개","mis":"M2-2-u2-X01"},{"t":"3개","mis":"M2-2-u2-X02"}],"explanation":["필통 한 개에 지우개가 2개씩이에요.","필통이 하나 늘면 지우개 2개가 더 생겨요.","곱하는 수가 1 커지면 곱은 2 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#4','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',1,'sa','auto','2 × 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2 × 6은 얼마인가요? 숫자로 쓰세요.","explanation":["2 × 6은 2의 6배예요.","2씩 뛰어 세면 2, 4, 6, 8, 10, 12.","그래서 2 × 6 = 12예요."],"variant_rule":{"mul":{"ask":"value","ks":[2],"pmax":81}},"answer":["12"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#5','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'mc','auto','2 × 4 = 8이에요. 이것을 이용하면 2 × 5는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"2 × 4 = 8이에요. 이것을 이용하면 2 × 5는 얼마인가요?","explanation":["2 × 5는 2 × 4보다 2만큼 더 커요.","8 + 2 = 10이에요.","한 번 더 더할 때는 곱하는 수 5가 아니라 2를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[2]}},"options":[{"t":"10","correct":true},{"t":"9","mis":"M2-2-u2-X01"},{"t":"13","mis":"M2-2-u2-X17"},{"t":"12","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#6','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'ox','auto','2 × 6은 2 × 5보다 1 커요.',ARRAY['M2-2-u2-X01']::text[],true,'{"seq":6,"concept":"M2-2-u2-C1","difficulty":2,"kind":"ox","stem":"2 × 6은 2 × 5보다 1 커요.","answer":"X","reason_options":[{"t":"2를 한 번 더 더하니까 2 커져요","correct":true},{"t":"곱하는 수가 1 커졌으니 곱도 1 커지니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["2 × 5 = 10, 2 × 6 = 12예요.","2를 한 번 더 더했으니 2만큼 커졌어요.","곱하는 수가 1 커지면 2단의 곱은 2씩 커져요."],"variant_rule":{"alt":[{"stem":"2 × 8은 2 × 7보다 2 커요.","answer":"O","reason_options":[{"t":"2를 한 번 더 더하니까 14에서 16이 되니까","correct":true},{"t":"곱하는 수가 1 커지면 곱도 1 커지니까","mis":"M2-2-u2-X01"}],"explanation":["2 × 7 = 14, 2 × 8 = 16이에요.","2를 한 번 더 더해 2만큼 커졌어요.","그래서 바른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#7','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C1","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"2 × 3","r":"6"},{"l":"2 × 7","r":"14"},{"l":"2 × 9","r":"18"}],"mis":"M2-2-u2-X02","explanation":["2 × 3은 2, 4, 6으로 6이에요.","2 × 7은 2씩 7번 뛰어 14예요.","2 × 9는 2씩 9번 뛰어 18이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"2 × 4","r":"8"},{"l":"2 × 6","r":"12"},{"l":"2 × 8","r":"16"}],"explanation":["2 × 4는 2, 4, 6, 8로 8이에요.","2 × 6은 2씩 6번 뛰어 12예요.","2 × 8은 2씩 8번 뛰어 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#8','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'mc','auto','로봇 한 대에 바퀴가 2개씩 있어요. 로봇 7대의 바퀴는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"로봇 한 대에 바퀴가 2개씩 있어요. 로봇 7대의 바퀴는 모두 몇 개인가요?","explanation":["로봇 한 대에 2개씩, 7대이면 2씩 7묶음이에요.","2 × 7 = 14예요.","바퀴는 모두 14개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[2]}},"options":[{"t":"14개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"7개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#9','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',2,'mc','auto','2 × □ = 16에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"2 × □ = 16에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["2단 곱셈구구에서 곱이 16인 것을 찾아요.","2씩 뛰어 세면 2, 4, 6, 8, 10, 12, 14, 16 — 8번이에요.","2 × 8 = 16이라 □는 8이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[2]}},"options":[{"t":"8","correct":true},{"t":"9","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_basic#10','math',2,2,'u2','L02','g2_2_math_u2_L02_basic','lesson_basic','M2-2-u2-C1',3,'error','auto','2 × 5를 구하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C1","difficulty":3,"kind":"error","stem":"2 × 5를 구하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「2 × 4 = 8에 5를 더하면 13이야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"서아 — 「2를 5번 더하면 10이야.」","mis":"M2-2-u2-X15"},{"t":"하루 — 「2 × 4 = 8에 2를 더하면 10이야.」","mis":"M2-2-u2-X15"}],"explanation":["2 × 5는 2 × 4보다 2만큼 커요.","지우는 2 대신 곱하는 수 5를 더했어요.","서아와 하루처럼 구하면 2 × 5 = 10이에요."],"variant_rule":{"alt":[{"stem":"2 × 7을 구하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「2 × 6 = 12에 7을 더하면 19야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"은솔 — 「2씩 7번 뛰어 세면 14야.」","mis":"M2-2-u2-X15"},{"t":"예린 — 「2 × 6 = 12에 2를 더하면 14야.」","mis":"M2-2-u2-X15"}],"explanation":["2 × 7은 2 × 6보다 2만큼 커요.","도윤이는 2 대신 곱하는 수 7을 더했어요.","2 × 7 = 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#1','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',2,'mc','auto','2 × 8은 2 × 7보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"2 × 8은 2 × 7보다 얼마 더 큰가요?","explanation":["2 × 7은 2를 7번, 2 × 8은 2를 8번 더한 것이에요.","2를 한 번 더 더했으니 2만큼 더 커요 — 14에서 16.","곱하는 수가 1 커지면 곱은 2만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[2]}},"options":[{"t":"2","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#2','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C1","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 2개씩 6줄이에요.","2의 6배이니 곱셈식으로 2 × 6이에요.","2 × 6 = 12, 모두 12개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[2],"pmax":45}},"options":[{"t":"2 × 6","correct":true},{"t":"2 + 6","mis":"M2-2-u2-X11"},{"t":"2 × 7","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🍅","k":2,"n":6,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#3','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','2단 곱셈구구의 곱이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":3,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"2단 곱셈구구의 곱이 아닌 것은 어느 것인가요?","options":[{"t":"15","correct":true},{"t":"12","mis":"M2-2-u2-X15"},{"t":"16","mis":"M2-2-u2-X15"},{"t":"18","mis":"M2-2-u2-X15"}],"explanation":["2단 곱셈구구의 곱은 2, 4, 6, 8, 10, 12, 14, 16, 18이에요.","2씩 뛰어 센 수에 15는 없어요.","「아닌 것」을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#4','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','2 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":4,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"2 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"2 × 5 = 10에 6을 더해요","correct":true},{"t":"2를 6번 더해요","mis":"M2-2-u2-X15"},{"t":"2 × 3 = 6을 두 번 더해요","mis":"M2-2-u2-X15"},{"t":"2 × 5 = 10에 2를 더해요","mis":"M2-2-u2-X15"}],"explanation":["2 × 6은 2를 6번 더한 12예요.","2 × 5에 더할 수는 6이 아니라 2예요 — 10 + 6 = 16은 틀려요.","2 × 3 = 6을 두 번 더해도 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#5','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','□ × 7 = 14에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":5,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"□ × 7 = 14에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 7번째 곱이 14인지 찾아요.","2 × 7 = 14예요 — 3 × 7 = 21이에요.","그래서 □는 2예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[2]}},"options":[{"t":"2","correct":true},{"t":"3","mis":"M2-2-u2-X02"},{"t":"1","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#6','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','신발 한 켤레는 2짝이에요. 우리 모둠 친구 7명이 신발을 한 켤레씩 신었어요. 신발은 모두 몇 짝인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02','M2-2-u2-X14']::text[],false,'{"seq":6,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"신발 한 켤레는 2짝이에요. 우리 모둠 친구 7명이 신발을 한 켤레씩 신었어요. 신발은 모두 몇 짝인가요?","options":[{"t":"14짝","correct":true},{"t":"9짝","mis":"M2-2-u2-X06"},{"t":"12짝","mis":"M2-2-u2-X02"},{"t":"7짝","mis":"M2-2-u2-X14"}],"explanation":["한 사람이 2짝씩, 7명이에요.","2 × 7 = 14예요.","그래서 신발은 모두 14짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#7','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',3,'mc','auto','로봇이 8대 있어요. 바퀴가 모두 몇 개인지 구하는 곱셈식과 답이 바른 것은 어느 것인가요? (로봇 한 대에 바퀴 2개)',ARRAY['M2-2-u2-X14','M2-2-u2-X11','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C1","difficulty":3,"kind":"mc","stem":"로봇이 8대 있어요. 바퀴가 모두 몇 개인지 구하는 곱셈식과 답이 바른 것은 어느 것인가요? (로봇 한 대에 바퀴 2개)","options":[{"t":"2 × 8 = 16","correct":true},{"t":"8 × 8 = 64","mis":"M2-2-u2-X14"},{"t":"2 + 8 = 10","mis":"M2-2-u2-X11"},{"t":"2 × 8 = 18","mis":"M2-2-u2-X02"}],"explanation":["한 대에 2개씩 — 한 묶음은 2예요.","8대이니 2 × 8이에요.","2씩 8번 뛰어 세면 16이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#8','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'essay','teacher','2 × 7을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C1","difficulty":4,"kind":"essay","stem":"2 × 7을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 2를 7번 더하면 2 + 2 + 2 + 2 + 2 + 2 + 2 = 14이다. 2 × 6 = 12에 2를 한 번 더 더하면 14이다.","scoring_points":["2를 7번 더하는 방법으로 14를 구했는가","2 × 6에 2를 더하는 방법으로 14를 구했는가","두 방법 모두 2 × 7 = 14라고 썼는가"]},"explanation":["2 × 7은 2를 7번 더한 것이에요.","2 × 6 = 12보다 2만큼 더 커요.","어떤 방법으로 구해도 14예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#9','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'essay','teacher','2 × 3, 2 × 4, 2 × 5의 곱을 구하고, 2단 곱셈구구에서 곱하는 수가 1씩 커지면 곱이 어떻게 되는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C1","difficulty":4,"kind":"essay","stem":"2 × 3, 2 × 4, 2 × 5의 곱을 구하고, 2단 곱셈구구에서 곱하는 수가 1씩 커지면 곱이 어떻게 되는지 설명해 보세요.","answer_guide":{"answer":"예: 2 × 3 = 6, 2 × 4 = 8, 2 × 5 = 10이다. 곱하는 수가 1씩 커지면 곱은 2씩 커진다. 2를 한 번씩 더 더하기 때문이다.","scoring_points":["세 곱을 바르게 구했는가","곱이 2씩 커진다고 썼는가","2를 한 번 더 더하기 때문이라고 까닭을 썼는가"]},"explanation":["6, 8, 10으로 2씩 커져요.","곱하는 수가 1 커지면 2를 한 번 더 더해요.","곱이 1씩 커지는 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L02_challenge#10','math',2,2,'u2','L02','g2_2_math_u2_L02_challenge','lesson_challenge','M2-2-u2-C1',4,'mc','auto','양말 한 켤레는 2짝이에요. 하린이는 양말 6켤레, 지호는 양말 4켤레를 가지고 있어요. 두 사람의 양말은 모두 몇 짝인가요?',ARRAY['M2-2-u2-X05','M2-2-u2-X18','M2-2-u2-X02']::text[],false,'{"seq":10,"concept":"M2-2-u2-C1","difficulty":4,"kind":"mc","stem":"양말 한 켤레는 2짝이에요. 하린이는 양말 6켤레, 지호는 양말 4켤레를 가지고 있어요. 두 사람의 양말은 모두 몇 짝인가요?","options":[{"t":"20짝","correct":true},{"t":"10짝","mis":"M2-2-u2-X05"},{"t":"12짝","mis":"M2-2-u2-X18"},{"t":"22짝","mis":"M2-2-u2-X02"}],"explanation":["하린이는 2 × 6 = 12짝이에요.","지호는 2 × 4 = 8짝이에요.","12 + 8 = 20이니 모두 20짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#1','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'mc','auto','그림을 보세요. 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":1,"concept":"M2-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 딸기는 모두 몇 개인가요?","explanation":["5개씩 3묶음이에요.","5씩 뛰어 세면 5, 10, 15.","딸기는 모두 15개예요."],"variant_rule":{"mul":{"ask":"total","ks":[5],"pmax":45}},"options":[{"t":"15개","correct":true},{"t":"8개","mis":"M2-2-u2-X06"},{"t":"3개","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#2','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'sa','auto','5씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["5씩 커지는 수예요.","15에서 5만큼 더 뛰면 20이에요.","5씩 4번 뛰어 센 수 — 5씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[5],"pmax":45}},"answer":["20"],"asset":{"type":"jump_row","cells":[5,10,15,null],"step":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#3','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'sa','auto','5 × 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 6은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 6은 5의 6배예요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30.","그래서 5 × 6 = 30이에요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["30"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#4','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',1,'mc','auto','쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 4개에 담긴 딸기의 수를 곱셈식으로 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X04','M2-2-u2-X11']::text[],true,'{"seq":4,"concept":"M2-2-u2-C2","difficulty":1,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 4개에 담긴 딸기의 수를 곱셈식으로 나타낸 것은 어느 것인가요?","options":[{"t":"5 × 4","correct":true},{"t":"4 × 4","mis":"M2-2-u2-X04"},{"t":"5 + 4","mis":"M2-2-u2-X11"}],"explanation":["쟁반 한 개에 5개씩 — 한 묶음은 5예요.","쟁반이 4개이니 5 × 4예요.","5 × 4 = 20이에요."],"variant_rule":{"alt":[{"stem":"한 손에 손가락이 5개씩 있어요. 손 3개의 손가락 수를 곱셈식으로 나타낸 것은 어느 것인가요?","options":[{"t":"5 × 3","correct":true},{"t":"3 × 3","mis":"M2-2-u2-X04"},{"t":"5 + 3","mis":"M2-2-u2-X11"}],"explanation":["한 손에 5개씩 — 한 묶음은 5예요.","손이 3개이니 5 × 3이에요.","5 × 3 = 15예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#5','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','5 × 5 = 25예요. 이것을 이용하면 5 × 6은 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5 × 5 = 25예요. 이것을 이용하면 5 × 6은 얼마인가요?","explanation":["5 × 6은 5 × 5보다 5만큼 더 커요.","25 + 5 = 30이에요.","한 번 더 더할 때는 곱하는 수 6이 아니라 5를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[5]}},"options":[{"t":"30","correct":true},{"t":"26","mis":"M2-2-u2-X01"},{"t":"31","mis":"M2-2-u2-X17"},{"t":"35","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#6','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'ox','auto','5단 곱셈구구의 곱은 일의 자리 숫자가 5, 0, 5, 0, …으로 되풀이돼요.',ARRAY['M2-2-u2-X16']::text[],true,'{"seq":6,"concept":"M2-2-u2-C2","difficulty":2,"kind":"ox","stem":"5단 곱셈구구의 곱은 일의 자리 숫자가 5, 0, 5, 0, …으로 되풀이돼요.","answer":"O","reason_options":[{"t":"5, 10, 15, 20처럼 일의 자리에 5와 0이 번갈아 나오니까","correct":true},{"t":"곱하는 수가 1, 2, 3으로 1씩 커지니까","mis":"M2-2-u2-X16"}],"mis":"M2-2-u2-X16","explanation":["5단의 곱은 5, 10, 15, 20, 25, 30, 35, 40, 45예요.","일의 자리 숫자만 보면 5, 0, 5, 0, …이에요.","그래서 바른 말이에요."],"variant_rule":{"alt":[{"stem":"5 × 7의 곱은 일의 자리 숫자가 0이에요.","answer":"X","reason_options":[{"t":"5 × 7 = 35라 일의 자리 숫자가 5니까","correct":true},{"t":"5단의 곱은 일의 자리가 늘 0이니까","mis":"M2-2-u2-X16"}],"explanation":["5 × 7 = 35예요.","5에 홀수 번을 곱하면 일의 자리가 5, 짝수 번을 곱하면 0이에요.","그래서 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#7','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C2","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"5 × 3","r":"15"},{"l":"5 × 6","r":"30"},{"l":"5 × 9","r":"45"}],"mis":"M2-2-u2-X02","explanation":["5 × 3은 5, 10, 15로 15예요.","5 × 6은 5씩 6번 뛰어 30이에요.","5 × 9는 5씩 9번 뛰어 45예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"5 × 2","r":"10"},{"l":"5 × 5","r":"25"},{"l":"5 × 8","r":"40"}],"explanation":["5 × 2는 5, 10으로 10이에요.","5 × 5는 5씩 5번 뛰어 25예요.","5 × 8은 5씩 8번 뛰어 40이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#8','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 6개의 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 6개의 딸기는 모두 몇 개인가요?","explanation":["쟁반 한 개에 5개씩, 6개이면 5씩 6묶음이에요.","5 × 6 = 30이에요.","딸기는 모두 30개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[5]}},"options":[{"t":"30개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"6개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#9','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',2,'mc','auto','5 × □ = 35에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5 × □ = 35에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["5단 곱셈구구에서 곱이 35인 것을 찾아요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30, 35 — 7번이에요.","5 × 7 = 35라 □는 7이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[5]}},"options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u2-X02"},{"t":"6","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_basic#10','math',2,2,'u2','L03','g2_2_math_u2_L03_basic','lesson_basic','M2-2-u2-C2',3,'error','auto','친구 6명이 손바닥을 하나씩 펼쳤어요. 펼친 손가락의 수를 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C2","difficulty":3,"kind":"error","stem":"친구 6명이 손바닥을 하나씩 펼쳤어요. 펼친 손가락의 수를 잘못 말한 친구는 누구인가요?","options":[{"t":"준우 — 「5 × 6이니까 11개야.」","correct":true,"mis_target":"M2-2-u2-X06"},{"t":"예린 — 「5씩 6번 뛰어 세면 30개야.」","mis":"M2-2-u2-X15"},{"t":"태민 — 「5 × 5 = 25에 5를 더하면 30개야.」","mis":"M2-2-u2-X15"}],"explanation":["손바닥 하나에 손가락 5개, 6명이니 5 × 6이에요.","준우는 5와 6을 더했어요.","5 × 6 = 30이니 30개예요."],"variant_rule":{"alt":[{"stem":"친구 4명이 손바닥을 하나씩 펼쳤어요. 펼친 손가락의 수를 잘못 말한 친구는 누구인가요?","options":[{"t":"아린 — 「5 × 4니까 9개야.」","correct":true,"mis_target":"M2-2-u2-X06"},{"t":"지안 — 「5, 10, 15, 20이니까 20개야.」","mis":"M2-2-u2-X15"},{"t":"하람 — 「5 × 3 = 15에 5를 더하면 20개야.」","mis":"M2-2-u2-X15"}],"explanation":["손바닥 하나에 손가락 5개, 4명이니 5 × 4예요.","아린이는 5와 4를 더했어요.","5 × 4 = 20이니 20개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#1','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',2,'mc','auto','5 × 4는 5 × 3보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"5 × 4는 5 × 3보다 얼마 더 큰가요?","explanation":["5 × 3은 5를 3번, 5 × 4는 5를 4번 더한 것이에요.","5를 한 번 더 더했으니 5만큼 더 커요 — 15에서 20.","곱하는 수가 1 커지면 곱은 5만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[5]}},"options":[{"t":"5","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"4","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#2','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 5송이씩 3줄이에요.","5의 3배이니 곱셈식으로 5 × 3이에요.","5 × 3 = 15, 모두 15송이예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[5],"pmax":45}},"options":[{"t":"5 × 3","correct":true},{"t":"5 + 3","mis":"M2-2-u2-X11"},{"t":"5 × 4","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🌷","k":5,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#3','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','5단 곱셈구구의 곱이 될 수 없는 수는 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":3,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"5단 곱셈구구의 곱이 될 수 없는 수는 어느 것인가요?","options":[{"t":"32","correct":true},{"t":"35","mis":"M2-2-u2-X15"},{"t":"40","mis":"M2-2-u2-X15"},{"t":"20","mis":"M2-2-u2-X15"}],"explanation":["5단의 곱은 일의 자리 숫자가 5 아니면 0이에요.","32는 일의 자리 숫자가 2라 5단의 곱이 아니에요.","35 = 5 × 7, 40 = 5 × 8, 20 = 5 × 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#4','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','5 × 8은 5 × 4를 몇 번 더한 것과 같은가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X04']::text[],false,'{"seq":4,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"5 × 8은 5 × 4를 몇 번 더한 것과 같은가요?","options":[{"t":"2번","correct":true},{"t":"4번","mis":"M2-2-u2-X17"},{"t":"8번","mis":"M2-2-u2-X04"}],"explanation":["5 × 4 = 20이에요.","20 + 20 = 40 = 5 × 8이에요.","5씩 8묶음은 5씩 4묶음이 두 개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#5','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','□ × 9 = 45에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":5,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"□ × 9 = 45에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 9번째 곱이 45인지 찾아요.","5 × 9 = 45예요 — 6 × 9 = 54예요.","그래서 □는 5예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[5]}},"options":[{"t":"5","correct":true},{"t":"6","mis":"M2-2-u2-X02"},{"t":"4","mis":"M2-2-u2-X02"},{"t":"36","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#6','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','한 묶음에 연필이 5자루씩 있어요. 7묶음 있으면 연필은 모두 몇 자루인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":6,"concept":"M2-2-u2-C2","difficulty":3,"kind":"mc","stem":"한 묶음에 연필이 5자루씩 있어요. 7묶음 있으면 연필은 모두 몇 자루인가요?","options":[{"t":"35자루","correct":true},{"t":"12자루","mis":"M2-2-u2-X06"},{"t":"30자루","mis":"M2-2-u2-X02"},{"t":"40자루","mis":"M2-2-u2-X02"}],"explanation":["한 묶음에 5자루씩, 7묶음이에요.","5 × 7 = 35예요.","5 × 6 = 30, 5 × 8 = 40과 헷갈리지 않게 7번인지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#7','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#8','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'essay','teacher','5 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C2","difficulty":4,"kind":"essay","stem":"5 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 5씩 6번 뛰어 세면 5, 10, 15, 20, 25, 30이다. 5 × 5 = 25에 5를 한 번 더 더하면 30이다. 그래서 5 × 6 = 30이다.","scoring_points":["한 가지 방법(뛰어 세기·여러 번 더하기)으로 30을 구했는가","다른 방법(5 × 5에 5 더하기 등)으로 30을 구했는가","5 × 6 = 30이라고 썼는가"]},"explanation":["5 × 6은 5를 6번 더한 것이에요.","5 × 5 = 25보다 5만큼 더 커요.","어느 방법으로든 30이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#9','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'essay','teacher','5단 곱셈구구의 곱을 모두 쓰고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C2","difficulty":4,"kind":"essay","stem":"5단 곱셈구구의 곱을 모두 쓰고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.","answer_guide":{"answer":"예: 5, 10, 15, 20, 25, 30, 35, 40, 45. 곱이 5씩 커진다. 일의 자리 숫자가 5, 0, 5, 0으로 되풀이된다.","scoring_points":["5단의 곱을 바르게 썼는가","곱이 5씩 커진다는 규칙을 썼는가","일의 자리 숫자가 5와 0으로 되풀이된다는 규칙을 썼는가"]},"explanation":["5단의 곱은 5씩 커져요.","일의 자리 숫자만 보면 5와 0이 번갈아 나와요.","이 규칙으로 5단의 곱을 쉽게 알아볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L03_challenge#10','math',2,2,'u2','L03','g2_2_math_u2_L03_challenge','lesson_challenge','M2-2-u2-C2',4,'mc','auto','한 손에 손가락이 5개씩 있어요. 친구 4명의 두 손 손가락은 모두 몇 개인가요?',ARRAY['M2-2-u2-X14','M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":10,"concept":"M2-2-u2-C2","difficulty":4,"kind":"mc","stem":"한 손에 손가락이 5개씩 있어요. 친구 4명의 두 손 손가락은 모두 몇 개인가요?","options":[{"t":"40개","correct":true},{"t":"20개","mis":"M2-2-u2-X14"},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"45개","mis":"M2-2-u2-X02"}],"explanation":["친구 4명의 손은 2 × 4 = 8개예요.","손 하나에 5개씩, 손 8개이니 5 × 8 = 40이에요.","한 손씩만 세면 20개가 되어 틀려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#1','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'mc','auto','그림을 보세요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":1,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"그림을 보세요. 물고기는 모두 몇 마리인가요?","explanation":["한 줄에 3마리씩 4줄이에요.","3씩 뛰어 세면 3, 6, 9, 12.","물고기는 모두 12마리예요."],"variant_rule":{"mul":{"ask":"total","look":"rows","ks":[3,6],"pmax":45}},"options":[{"t":"12마리","correct":true},{"t":"7마리","mis":"M2-2-u2-X06"},{"t":"4마리","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"🐟","k":3,"n":4,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#2','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'sa','auto','3씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"3씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["3씩 커지는 수예요.","12에서 3만큼 더 뛰면 15예요.","3씩 5번 뛰어 센 수 — 3씩 5묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[3,6],"pmax":45}},"answer":["15"],"asset":{"type":"jump_row","cells":[3,6,9,12,null],"step":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#3','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'sa','auto','6 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"6 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["6 × 3은 6의 3배예요.","6씩 뛰어 세면 6, 12, 18.","그래서 6 × 3 = 18이에요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#4','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',1,'mc','auto','노란색 물고기가 한 줄에 3마리씩 5줄 있어요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C3","difficulty":1,"kind":"mc","stem":"노란색 물고기가 한 줄에 3마리씩 5줄 있어요. 물고기는 모두 몇 마리인가요?","options":[{"t":"15마리","correct":true},{"t":"8마리","mis":"M2-2-u2-X06"},{"t":"18마리","mis":"M2-2-u2-X02"}],"explanation":["한 줄에 3마리씩, 5줄이에요.","3 × 5 = 15예요.","3, 6, 9, 12, 15로 뛰어 세어도 15마리예요."],"variant_rule":{"alt":[{"stem":"구슬이 한 봉지에 6개씩 3봉지 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"18개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"24개","mis":"M2-2-u2-X02"}],"explanation":["한 봉지에 6개씩, 3봉지예요.","6 × 3 = 18이에요.","6, 12, 18로 뛰어 세어도 18개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#5','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','6 × 3 = 18이에요. 이것을 이용하면 6 × 4는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"6 × 3 = 18이에요. 이것을 이용하면 6 × 4는 얼마인가요?","explanation":["6 × 4는 6 × 3보다 6만큼 더 커요.","18 + 6 = 24예요.","한 번 더 더할 때는 곱하는 수 4가 아니라 6을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[3,6]}},"options":[{"t":"24","correct":true},{"t":"19","mis":"M2-2-u2-X01"},{"t":"22","mis":"M2-2-u2-X17"},{"t":"30","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#6','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'ox','auto','6 × 5와 5 × 6은 곱이 같아요.',ARRAY['M2-2-u2-X13']::text[],true,'{"seq":6,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 5와 5 × 6은 곱이 같아요.","answer":"O","reason_options":[{"t":"6씩 5묶음과 5씩 6묶음은 같은 30개를 다르게 묶은 것이니까","correct":true},{"t":"앞의 수가 크면 곱도 크니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["6 × 5 = 30이에요.","5 × 6 = 30이에요.","두 수를 바꾸어 곱해도 곱은 같아요 — 6 × 5를 5단으로 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"3 × 4를 두 번 더하면 6 × 4와 같아요.","answer":"O","reason_options":[{"t":"3씩 8묶음은 6씩 4묶음과 같아서 12 + 12 = 24니까","correct":true},{"t":"3단과 6단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"explanation":["3 × 4 = 12예요.","12 + 12 = 24 = 6 × 4예요.","6단의 곱은 같은 수를 곱한 3단의 곱의 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#7','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C3","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"3 × 4","r":"12"},{"l":"6 × 4","r":"24"},{"l":"6 × 7","r":"42"}],"mis":"M2-2-u2-X02","explanation":["3 × 4는 3씩 4번 뛰어 12예요.","6 × 4는 12의 2배, 24예요.","6 × 7은 6씩 7번 뛰어 42예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"3 × 8","r":"24"},{"l":"6 × 3","r":"18"},{"l":"6 × 9","r":"54"}],"explanation":["3 × 8은 3씩 8번 뛰어 24예요.","6 × 3은 6, 12, 18로 18이에요.","6 × 9는 6씩 9번 뛰어 54예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#8','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','어항 한 개에 물고기가 3마리씩 있어요. 어항 4개의 물고기는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"어항 한 개에 물고기가 3마리씩 있어요. 어항 4개의 물고기는 모두 몇 마리인가요?","explanation":["어항 한 개에 3마리씩, 4개이면 3씩 4묶음이에요.","3 × 4 = 12예요.","물고기는 모두 12마리예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[3,6]}},"options":[{"t":"12마리","correct":true},{"t":"7마리","mis":"M2-2-u2-X06"},{"t":"4마리","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#9','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',2,'mc','auto','3 × □ = 24에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"3 × □ = 24에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["3단 곱셈구구에서 곱이 24인 것을 찾아요.","3씩 뛰어 세면 3, 6, 9, 12, 15, 18, 21, 24 — 8번이에요.","3 × 8 = 24라 □는 8이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[3,6]}},"options":[{"t":"8","correct":true},{"t":"9","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_basic#10','math',2,2,'u2','L04','g2_2_math_u2_L04_basic','lesson_basic','M2-2-u2-C3',3,'mc','auto','장난감이 6개씩 4묶음 있어요. 같은 장난감을 3개씩 묶으면 몇 묶음이 될까요?',ARRAY['M2-2-u2-X10','M2-2-u2-X05']::text[],true,'{"seq":10,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"장난감이 6개씩 4묶음 있어요. 같은 장난감을 3개씩 묶으면 몇 묶음이 될까요?","options":[{"t":"8묶음","correct":true},{"t":"4묶음","mis":"M2-2-u2-X10"},{"t":"24묶음","mis":"M2-2-u2-X05"}],"explanation":["6 × 4 = 24이니 장난감은 24개예요.","6개씩 한 묶음은 3개씩 두 묶음이에요.","그래서 3개씩 8묶음 — 3 × 8 = 24예요."],"variant_rule":{"alt":[{"stem":"구슬이 3개씩 6묶음 있어요. 같은 구슬을 6개씩 묶으면 몇 묶음이 될까요?","options":[{"t":"3묶음","correct":true},{"t":"6묶음","mis":"M2-2-u2-X10"},{"t":"18묶음","mis":"M2-2-u2-X05"}],"explanation":["3 × 6 = 18이니 구슬은 18개예요.","3개씩 두 묶음이 6개씩 한 묶음이에요.","그래서 6개씩 3묶음 — 6 × 3 = 18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#1','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',2,'mc','auto','6 × 7은 6 × 6보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"6 × 7은 6 × 6보다 얼마 더 큰가요?","explanation":["6 × 6은 6을 6번, 6 × 7은 6을 7번 더한 것이에요.","6을 한 번 더 더했으니 6만큼 더 커요 — 36에서 42.","곱하는 수가 1 커지면 곱은 6만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[3,6]}},"options":[{"t":"6","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"7","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#2','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C3","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 6개씩 3줄이에요.","6의 3배이니 곱셈식으로 6 × 3이에요.","6 × 3 = 18, 모두 18개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[3,6],"pmax":45}},"options":[{"t":"6 × 3","correct":true},{"t":"6 + 3","mis":"M2-2-u2-X11"},{"t":"6 × 4","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🍬","k":6,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#3','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','3 × 6과 6 × 3을 바르게 설명한 것은 어느 것인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X06']::text[],false,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"3 × 6과 6 × 3을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"곱이 18로 같아요","correct":true},{"t":"6 × 3이 더 커요","mis":"M2-2-u2-X13"},{"t":"곱이 9로 같아요","mis":"M2-2-u2-X06"}],"explanation":["3 × 6은 3씩 6묶음, 6 × 3은 6씩 3묶음이에요.","둘 다 18이에요.","두 수를 바꾸어 곱해도 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#4','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','6 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":4,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"6 × 6을 구하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"6 × 5 = 30에 5를 더해요","correct":true},{"t":"6 × 5 = 30에 6을 더해요","mis":"M2-2-u2-X15"},{"t":"3 × 6 = 18을 두 번 더해요","mis":"M2-2-u2-X15"},{"t":"6을 6번 더해요","mis":"M2-2-u2-X15"}],"explanation":["6 × 6 = 36이에요.","6 × 5에 더할 수는 6이에요 — 30 + 5 = 35는 틀려요.","18 + 18 = 36, 6을 6번 더해도 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#5','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#6','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','같은 수를 곱할 때 6단 곱셈구구의 곱은 3단 곱셈구구의 곱의 몇 배인가요?',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":6,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"같은 수를 곱할 때 6단 곱셈구구의 곱은 3단 곱셈구구의 곱의 몇 배인가요?","options":[{"t":"2배","correct":true},{"t":"3배","mis":"M2-2-u2-X10"},{"t":"6배","mis":"M2-2-u2-X10"}],"explanation":["3 × 4 = 12, 6 × 4 = 24예요.","24는 12의 2배예요.","6씩 한 묶음은 3씩 두 묶음이라 6단의 곱은 3단의 곱의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#7','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',3,'mc','auto','□ × 7 = 42에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":7,"concept":"M2-2-u2-C3","difficulty":3,"kind":"mc","stem":"□ × 7 = 42에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 7번째 곱이 42인지 찾아요.","6 × 7 = 42예요 — 7 × 7 = 49예요.","그래서 □는 6이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[3,6]}},"options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u2-X02"},{"t":"5","mis":"M2-2-u2-X02"},{"t":"35","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#8','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'essay','teacher','6 × 5를 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C3","difficulty":4,"kind":"essay","stem":"6 × 5를 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 6 × 4 = 24에 6을 한 번 더 더하면 30이다. 6씩 5묶음은 5씩 6묶음으로 다르게 묶을 수 있으니 5 × 6 = 30이다.","scoring_points":["6 × 4에 6을 더하는 방법으로 30을 구했는가","5 × 6처럼 다르게 묶거나 다른 방법으로 30을 구했는가","6 × 5 = 30이라고 썼는가"]},"explanation":["6 × 5는 6 × 4보다 6만큼 커요.","6씩 5묶음을 5씩 6묶음으로 보면 5단으로 구할 수 있어요.","어느 방법으로든 30이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#9','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'essay','teacher','3단 곱셈구구와 6단 곱셈구구가 어떻게 이어져 있는지 3 × 4와 6 × 4를 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C3","difficulty":4,"kind":"essay","stem":"3단 곱셈구구와 6단 곱셈구구가 어떻게 이어져 있는지 3 × 4와 6 × 4를 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 3 × 4 = 12, 6 × 4 = 24이다. 6씩 한 묶음은 3씩 두 묶음이므로 6 × 4는 3 × 4를 두 번 더한 것과 같다. 6단의 곱은 3단의 곱의 2배이다.","scoring_points":["두 곱을 바르게 구했는가","6씩 한 묶음이 3씩 두 묶음이라는 것을 썼는가","6단의 곱이 3단의 곱의 2배라고 썼는가"]},"explanation":["3 × 4 = 12, 6 × 4 = 24예요.","24는 12 + 12예요.","그래서 6단은 3단을 두 번 더한 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L04_challenge#10','math',2,2,'u2','L04','g2_2_math_u2_L04_challenge','lesson_challenge','M2-2-u2-C3',4,'mc','auto','한 상자에 컵케이크가 6개씩 들어 있어요. 5상자 가운데 3개를 먹었어요. 남은 컵케이크는 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":10,"concept":"M2-2-u2-C3","difficulty":4,"kind":"mc","stem":"한 상자에 컵케이크가 6개씩 들어 있어요. 5상자 가운데 3개를 먹었어요. 남은 컵케이크는 몇 개인가요?","options":[{"t":"27개","correct":true},{"t":"30개","mis":"M2-2-u2-X18"},{"t":"8개","mis":"M2-2-u2-X06"},{"t":"33개","mis":"M2-2-u2-X06"}],"explanation":["6 × 5 = 30이니 처음에 30개였어요.","그중 3개를 먹었어요.","30 − 3 = 27이니 27개가 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#1','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'mc','auto','그림을 보세요. 당근은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"그림을 보세요. 당근은 모두 몇 개인가요?","explanation":["4개씩 5묶음이에요.","4씩 뛰어 세면 4, 8, 12, 16, 20.","당근은 모두 20개예요."],"variant_rule":{"mul":{"ask":"total","ks":[4,8],"pmax":45}},"options":[{"t":"20개","correct":true},{"t":"9개","mis":"M2-2-u2-X06"},{"t":"5개","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"🥕","k":4,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#2','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'sa','auto','4씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C4","difficulty":1,"kind":"sa","stem":"4씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["4씩 커지는 수예요.","20에서 4만큼 더 뛰면 24예요.","4씩 6번 뛰어 센 수 — 4씩 6묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[4,8],"pmax":45}},"answer":["24"],"asset":{"type":"jump_row","cells":[4,8,12,16,20,null],"step":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#3','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'sa','auto','8 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C4","difficulty":1,"kind":"sa","stem":"8 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["8 × 3은 8의 3배예요.","8씩 뛰어 세면 8, 16, 24.","그래서 8 × 3 = 24예요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"answer":["24"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#4','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',1,'mc','auto','로봇이 한 줄에 4대씩 서 있어요. 6줄이면 로봇은 모두 몇 대인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"로봇이 한 줄에 4대씩 서 있어요. 6줄이면 로봇은 모두 몇 대인가요?","options":[{"t":"24대","correct":true},{"t":"10대","mis":"M2-2-u2-X06"},{"t":"28대","mis":"M2-2-u2-X02"}],"explanation":["한 줄에 4대씩, 6줄이에요.","4 × 6 = 24예요.","4 × 7 = 28과 헷갈리지 않게 줄 수를 확인해요."],"variant_rule":{"alt":[{"stem":"우유가 한 줄에 8갑씩 3줄 있어요. 우유는 모두 몇 갑인가요?","options":[{"t":"24갑","correct":true},{"t":"11갑","mis":"M2-2-u2-X06"},{"t":"32갑","mis":"M2-2-u2-X02"}],"explanation":["한 줄에 8갑씩, 3줄이에요.","8 × 3 = 24예요.","8 × 4 = 32와 헷갈리지 않게 줄 수를 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#5','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','8 × 3 = 24예요. 이것을 이용하면 8 × 4는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 3 = 24예요. 이것을 이용하면 8 × 4는 얼마인가요?","explanation":["8 × 4는 8 × 3보다 8만큼 더 커요.","24 + 8 = 32예요.","한 번 더 더할 때는 곱하는 수 4가 아니라 8을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"32","correct":true},{"t":"25","mis":"M2-2-u2-X01"},{"t":"28","mis":"M2-2-u2-X17"},{"t":"40","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#6','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'ox','auto','8 × 6은 8 × 3을 두 번 더한 것과 같아요.',ARRAY['M2-2-u2-X17']::text[],true,'{"seq":6,"concept":"M2-2-u2-C4","difficulty":2,"kind":"ox","stem":"8 × 6은 8 × 3을 두 번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"8씩 6묶음은 8씩 3묶음이 두 개니까","correct":true},{"t":"8 × 3에 3을 더하면 8 × 6이 되니까","mis":"M2-2-u2-X17"}],"mis":"M2-2-u2-X17","explanation":["8 × 3 = 24예요.","24 + 24 = 48 = 8 × 6이에요.","8 × 6을 8 × 3 두 번으로 나누어 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"8 × 4는 4 × 4의 2배예요.","answer":"O","reason_options":[{"t":"8씩 한 묶음은 4씩 두 묶음이라 16의 2배 32니까","correct":true},{"t":"4단과 8단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"explanation":["4 × 4 = 16, 8 × 4 = 32예요.","32는 16의 2배예요.","같은 수를 곱할 때 8단의 곱은 4단의 곱의 2배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#7','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C4","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"4 × 5","r":"20"},{"l":"8 × 5","r":"40"},{"l":"4 × 9","r":"36"}],"mis":"M2-2-u2-X02","explanation":["4 × 5는 4씩 5번 뛰어 20이에요.","8 × 5는 20의 2배, 40이에요.","4 × 9는 4씩 9번 뛰어 36이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"8 × 7","r":"56"},{"l":"4 × 7","r":"28"},{"l":"8 × 2","r":"16"}],"explanation":["8 × 7은 28의 2배, 56이에요.","4 × 7은 4씩 7번 뛰어 28이에요.","8 × 2는 8, 16으로 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#8','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','봉투 한 개에 색종이가 4장씩 있어요. 봉투 6개의 색종이는 모두 몇 장인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"봉투 한 개에 색종이가 4장씩 있어요. 봉투 6개의 색종이는 모두 몇 장인가요?","explanation":["봉투 한 개에 4장씩, 6개이면 4씩 6묶음이에요.","4 × 6 = 24예요.","색종이는 모두 24장이에요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[4,8]}},"options":[{"t":"24장","correct":true},{"t":"10장","mis":"M2-2-u2-X06"},{"t":"6장","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#9','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',2,'mc','auto','8 × □ = 56에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × □ = 56에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["8단 곱셈구구에서 곱이 56인 것을 찾아요.","8씩 뛰어 세면 8, 16, 24, 32, 40, 48, 56 — 7번이에요.","8 × 7 = 56이라 □는 7이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[4,8]}},"options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u2-X02"},{"t":"6","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_basic#10','math',2,2,'u2','L05','g2_2_math_u2_L05_basic','lesson_basic','M2-2-u2-C4',3,'mc','auto','우유가 4갑씩 6줄 있어요. 같은 우유를 8갑씩 놓으면 몇 줄이 될까요?',ARRAY['M2-2-u2-X10']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"우유가 4갑씩 6줄 있어요. 같은 우유를 8갑씩 놓으면 몇 줄이 될까요?","options":[{"t":"3줄","correct":true},{"t":"6줄","mis":"M2-2-u2-X10"},{"t":"12줄","mis":"M2-2-u2-X10"}],"explanation":["4 × 6 = 24이니 우유는 24갑이에요.","4갑씩 두 줄이 8갑씩 한 줄이에요.","그래서 8갑씩 3줄 — 8 × 3 = 24예요."],"variant_rule":{"alt":[{"stem":"구슬이 8개씩 2줄 있어요. 같은 구슬을 4개씩 놓으면 몇 줄이 될까요?","options":[{"t":"4줄","correct":true},{"t":"2줄","mis":"M2-2-u2-X10"},{"t":"8줄","mis":"M2-2-u2-X10"}],"explanation":["8 × 2 = 16이니 구슬은 16개예요.","8개씩 한 줄은 4개씩 두 줄이에요.","그래서 4개씩 4줄 — 4 × 4 = 16이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#1','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',2,'mc','auto','8 × 6은 8 × 5보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 6은 8 × 5보다 얼마 더 큰가요?","explanation":["8 × 5는 8을 5번, 8 × 6은 8을 6번 더한 것이에요.","8을 한 번 더 더했으니 8만큼 더 커요 — 40에서 48.","곱하는 수가 1 커지면 곱은 8만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[4,8]}},"options":[{"t":"8","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"6","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#2','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 4개씩 7줄이에요.","4의 7배이니 곱셈식으로 4 × 7이에요.","4 × 7 = 28, 모두 28개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[4,8],"pmax":45}},"options":[{"t":"4 × 7","correct":true},{"t":"4 + 7","mis":"M2-2-u2-X11"},{"t":"4 × 8","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🍪","k":4,"n":7,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#3','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','8 × 5를 구하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X11']::text[],false,'{"seq":3,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"8 × 5를 구하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"5개씩 8묶음으로 보아 5 × 8을 구해요","correct":true},{"t":"8 × 4 = 32에 5를 더해요","mis":"M2-2-u2-X17"},{"t":"8과 5를 더해요","mis":"M2-2-u2-X11"}],"explanation":["8씩 5묶음은 5씩 8묶음으로 다르게 묶을 수 있어요.","5 × 8 = 40이에요.","8 × 4 = 32에 더할 수는 5가 아니라 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#4','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','4단 곱셈구구의 곱도 되고 8단 곱셈구구의 곱도 되는 수는 어느 것인가요?',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"4단 곱셈구구의 곱도 되고 8단 곱셈구구의 곱도 되는 수는 어느 것인가요?","options":[{"t":"24","correct":true},{"t":"20","mis":"M2-2-u2-X10"},{"t":"28","mis":"M2-2-u2-X10"},{"t":"12","mis":"M2-2-u2-X10"}],"explanation":["24 = 4 × 6이고 24 = 8 × 3이에요.","20 = 4 × 5, 28 = 4 × 7, 12 = 4 × 3은 8단의 곱이 아니에요.","8단의 곱은 모두 4단의 곱이기도 해요(8 × 1부터 8 × 4까지)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#5','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#6','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','□ × 9 = 36에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":6,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"□ × 9 = 36에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 9번째 곱이 36인지 찾아요.","4 × 9 = 36이에요 — 5 × 9 = 45예요.","그래서 □는 4예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[4,8]}},"options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u2-X02"},{"t":"3","mis":"M2-2-u2-X02"},{"t":"27","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#7','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',3,'mc','auto','거미 한 마리의 다리는 8개예요. 거미 4마리의 다리는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C4","difficulty":3,"kind":"mc","stem":"거미 한 마리의 다리는 8개예요. 거미 4마리의 다리는 모두 몇 개인가요?","options":[{"t":"32개","correct":true},{"t":"12개","mis":"M2-2-u2-X06"},{"t":"24개","mis":"M2-2-u2-X02"},{"t":"36개","mis":"M2-2-u2-X02"}],"explanation":["한 마리에 8개씩, 4마리예요.","8 × 4 = 32예요.","8 × 3 = 24, 8 × 4 = 32 — 마리 수만큼 곱했는지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#8','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'essay','teacher','8 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C4","difficulty":4,"kind":"essay","stem":"8 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 8 × 5 = 40에 8을 한 번 더 더하면 48이다. 8 × 3 = 24를 두 번 더하면 24 + 24 = 48이다.","scoring_points":["한 가지 방법(8 × 5에 8 더하기 등)으로 48을 구했는가","다른 방법(8 × 3 두 번 더하기·4 × 6의 2배 등)으로 48을 구했는가","8 × 6 = 48이라고 썼는가"]},"explanation":["8 × 6은 8 × 5보다 8만큼 커요.","8씩 6묶음은 8씩 3묶음이 두 개예요.","어느 방법으로든 48이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#9','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'essay','teacher','우유가 4갑씩 6줄 놓여 있어요. 이것을 8갑씩 다시 놓으면 몇 줄인지 구하고, 4단과 8단이 어떻게 이어져 있는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C4","difficulty":4,"kind":"essay","stem":"우유가 4갑씩 6줄 놓여 있어요. 이것을 8갑씩 다시 놓으면 몇 줄인지 구하고, 4단과 8단이 어떻게 이어져 있는지 설명해 보세요.","answer_guide":{"answer":"예: 4 × 6 = 24갑이다. 4갑씩 두 줄을 합치면 8갑씩 한 줄이 되므로 8갑씩 3줄, 8 × 3 = 24이다. 8단의 곱은 같은 수를 곱한 4단의 곱의 2배이다.","scoring_points":["우유가 24갑임을 구했는가","8갑씩 3줄이 된다고 썼는가","4갑씩 두 줄이 8갑씩 한 줄이라는 관계를 썼는가"]},"explanation":["4 × 6 = 24예요.","4씩 두 묶음이 8이에요.","그래서 4갑씩 6줄은 8갑씩 3줄과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L05_challenge#10','math',2,2,'u2','L05','g2_2_math_u2_L05_challenge','lesson_challenge','M2-2-u2-C4',4,'mc','auto','구슬을 하린이는 4개씩 7묶음, 지호는 8개씩 3묶음 가지고 있어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u2-X19','M2-2-u2-X13','M2-2-u2-X02']::text[],false,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":4,"kind":"mc","stem":"구슬을 하린이는 4개씩 7묶음, 지호는 8개씩 3묶음 가지고 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"하린이가 4개 더 많아요","correct":true},{"t":"지호가 4개 더 많아요","mis":"M2-2-u2-X19"},{"t":"두 사람의 구슬 수가 같아요","mis":"M2-2-u2-X13"},{"t":"하린이가 2개 더 많아요","mis":"M2-2-u2-X02"}],"explanation":["하린이는 4 × 7 = 28개예요.","지호는 8 × 3 = 24개예요.","28 − 24 = 4이니 하린이가 4개 더 많아요 — 8이 크다고 지호가 많은 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#1','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'sa','auto','7씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"7씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["7씩 커지는 수예요.","21에서 7만큼 더 뛰면 28이에요.","7씩 4번 뛰어 센 수 — 7씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[7],"pmax":45}},"answer":["28"],"asset":{"type":"jump_row","cells":[7,14,21,null],"step":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#2','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'sa','auto','7 × 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C5","difficulty":1,"kind":"sa","stem":"7 × 2는 얼마인가요? 숫자로 쓰세요.","explanation":["7 × 2는 7의 2배예요.","7씩 뛰어 세면 7, 14.","그래서 7 × 2 = 14예요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"answer":["14"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#3','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'mc','auto','그림을 보세요. 별은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X05']::text[],true,'{"seq":3,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"그림을 보세요. 별은 모두 몇 개인가요?","explanation":["7개씩 3묶음이에요.","7씩 뛰어 세면 7, 14, 21.","별은 모두 21개예요."],"variant_rule":{"mul":{"ask":"total","ks":[7],"pmax":45}},"options":[{"t":"21개","correct":true},{"t":"10개","mis":"M2-2-u2-X06"},{"t":"3개","mis":"M2-2-u2-X05"}],"asset":{"type":"mul_groups","item":"⭐","k":7,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#4','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',1,'mc','auto','로봇이 한 번 움직일 때마다 7칸씩 가요. 로봇이 3번 움직이면 모두 몇 칸 가나요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"로봇이 한 번 움직일 때마다 7칸씩 가요. 로봇이 3번 움직이면 모두 몇 칸 가나요?","options":[{"t":"21칸","correct":true},{"t":"10칸","mis":"M2-2-u2-X06"},{"t":"14칸","mis":"M2-2-u2-X02"}],"explanation":["한 번에 7칸씩, 3번이에요.","7 × 3 = 21이에요.","7, 14, 21로 뛰어 세어도 21칸이에요."],"variant_rule":{"alt":[{"stem":"로봇이 한 번 움직일 때마다 7칸씩 가요. 로봇이 4번 움직이면 모두 몇 칸 가나요?","options":[{"t":"28칸","correct":true},{"t":"11칸","mis":"M2-2-u2-X06"},{"t":"21칸","mis":"M2-2-u2-X02"}],"explanation":["한 번에 7칸씩, 4번이에요.","7 × 4 = 28이에요.","7, 14, 21, 28로 뛰어 세어도 28칸이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#5','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','7 × 5 = 35예요. 이것을 이용하면 7 × 6은 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 5 = 35예요. 이것을 이용하면 7 × 6은 얼마인가요?","explanation":["7 × 6은 7 × 5보다 7만큼 더 커요.","35 + 7 = 42예요.","한 번 더 더할 때는 곱하는 수 6이 아니라 7을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[7]}},"options":[{"t":"42","correct":true},{"t":"36","mis":"M2-2-u2-X01"},{"t":"41","mis":"M2-2-u2-X17"},{"t":"49","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#6','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'ox','auto','7 × 6과 6 × 7은 곱이 같아요.',ARRAY['M2-2-u2-X13']::text[],true,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":2,"kind":"ox","stem":"7 × 6과 6 × 7은 곱이 같아요.","answer":"O","reason_options":[{"t":"7씩 6줄과 6씩 7줄은 같은 42개를 다르게 묶은 것이니까","correct":true},{"t":"곱하는 두 수의 순서가 바뀌면 곱도 바뀌니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["7 × 6 = 42예요.","6 × 7 = 42예요.","그래서 7 × 6은 6단으로도 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"7 × 5 = 35에 5를 더하면 7 × 6이에요.","answer":"X","reason_options":[{"t":"35에 7을 더해야 7 × 6 = 42가 되니까","correct":true},{"t":"곱하는 수만큼 더하면 되니까","mis":"M2-2-u2-X17"}],"explanation":["7 × 6은 7 × 5보다 7만큼 커요.","35 + 7 = 42예요.","35 + 5 = 40은 7 × 6이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#7','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C5","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"7 × 3","r":"21"},{"l":"7 × 5","r":"35"},{"l":"7 × 8","r":"56"}],"mis":"M2-2-u2-X02","explanation":["7 × 3은 7, 14, 21로 21이에요.","7 × 5는 7씩 5번 뛰어 35예요.","7 × 8은 7씩 8번 뛰어 56이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"7 × 4","r":"28"},{"l":"7 × 6","r":"42"},{"l":"7 × 9","r":"63"}],"explanation":["7 × 4는 7씩 4번 뛰어 28이에요.","7 × 6은 7씩 6번 뛰어 42예요.","7 × 9는 7씩 9번 뛰어 63이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#8','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','주머니 한 개에 구슬이 7개씩 있어요. 주머니 5개의 구슬은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":8,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"주머니 한 개에 구슬이 7개씩 있어요. 주머니 5개의 구슬은 모두 몇 개인가요?","explanation":["주머니 한 개에 7개씩, 5개이면 7씩 5묶음이에요.","7 × 5 = 35예요.","구슬은 모두 35개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[7]}},"options":[{"t":"35개","correct":true},{"t":"12개","mis":"M2-2-u2-X06"},{"t":"5개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#9','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',2,'mc','auto','7 × □ = 56에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":9,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × □ = 56에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["7단 곱셈구구에서 곱이 56인 것을 찾아요.","7씩 뛰어 세면 7, 14, 21, 28, 35, 42, 49, 56 — 8번이에요.","7 × 8 = 56이라 □는 8이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[7]}},"options":[{"t":"8","correct":true},{"t":"9","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_basic#10','math',2,2,'u2','L06','g2_2_math_u2_L06_basic','lesson_basic','M2-2-u2-C5',3,'error','auto','7씩 뛰는 로봇이 수직선에서 7 × 3인 21까지 왔어요. 7 × 5까지 가려면 얼마나 더 가야 하는지 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C5","difficulty":3,"kind":"error","stem":"7씩 뛰는 로봇이 수직선에서 7 × 3인 21까지 왔어요. 7 × 5까지 가려면 얼마나 더 가야 하는지 잘못 말한 친구는 누구인가요?","options":[{"t":"다예 — 「21에서 2만큼 더 가면 돼.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"곰이 — 「7 × 2만큼, 14만큼 더 가야 해.」","mis":"M2-2-u2-X15"},{"t":"펭이 — 「7 × 5 = 35니까 35까지 가야 해.」","mis":"M2-2-u2-X15"}],"explanation":["3번 간 로봇이 5번까지 가려면 2번 더 가야 해요.","한 번에 7칸씩이니 7 × 2 = 14만큼 더 가요 — 21 + 14 = 35예요.","다예는 7 × 2 대신 2만 더했어요."],"variant_rule":{"alt":[{"stem":"7씩 뛰는 로봇이 수직선에서 7 × 4인 28까지 왔어요. 7 × 6까지 가려면 얼마나 더 가야 하는지 잘못 말한 친구는 누구인가요?","options":[{"t":"하루 — 「28에서 2만큼 더 가면 돼.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"서아 — 「7 × 2만큼, 14만큼 더 가야 해.」","mis":"M2-2-u2-X15"},{"t":"지우 — 「7 × 6 = 42니까 42까지 가야 해.」","mis":"M2-2-u2-X15"}],"explanation":["4번 간 로봇이 6번까지 가려면 2번 더 가야 해요.","7 × 2 = 14만큼 더 가요 — 28 + 14 = 42예요.","하루는 7 × 2 대신 2만 더했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#1','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',2,'mc','auto','7 × 9는 7 × 8보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":1,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 9는 7 × 8보다 얼마 더 큰가요?","explanation":["7 × 8은 7을 8번, 7 × 9는 7을 9번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 56에서 63.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"9","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#2','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":2,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 7송이씩 4줄이에요.","7의 4배이니 곱셈식으로 7 × 4예요.","7 × 4 = 28, 모두 28송이예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows","ks":[7],"pmax":45}},"options":[{"t":"7 × 4","correct":true},{"t":"7 + 4","mis":"M2-2-u2-X11"},{"t":"7 × 5","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"🌷","k":7,"n":4,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#3','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','사탕이 7개씩 6봉지 있어요. 사탕의 수를 바르게 구한 것은 어느 것인가요?',ARRAY['M2-2-u2-X03','M2-2-u2-X11']::text[],false,'{"seq":3,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"사탕이 7개씩 6봉지 있어요. 사탕의 수를 바르게 구한 것은 어느 것인가요?","options":[{"t":"7 × 6 = 42","correct":true},{"t":"7 × 5 = 35","mis":"M2-2-u2-X03"},{"t":"7 + 6 = 13","mis":"M2-2-u2-X11"}],"explanation":["한 봉지에 7개씩, 6봉지예요.","7 × 6이에요.","7 × 5 = 35에 7을 더하면 42예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#4','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','의자가 한 줄에 6개씩 7줄 있어요. 의자의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],false,'{"seq":4,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"의자가 한 줄에 6개씩 7줄 있어요. 의자의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"7 × 6","correct":true},{"t":"6 + 7","mis":"M2-2-u2-X11"},{"t":"6 × 6","mis":"M2-2-u2-X03"},{"t":"7 × 7","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 6개씩 7줄이니 6 × 7 = 42예요.","두 수를 바꾸어 곱해도 곱이 같아요 — 7 × 6 = 42예요.","그래서 7 × 6으로도 구할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#5','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#6','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','□ × 6 = 42에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":6,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"□ × 6 = 42에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 6번째 곱이 42인지 찾아요.","7 × 6 = 42예요 — 8 × 6 = 48이에요.","그래서 □는 7이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u2-X02"},{"t":"6","mis":"M2-2-u2-X02"},{"t":"36","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#7','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',3,'mc','auto','일주일은 7일이에요. 3주와 2일은 모두 며칠인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C5","difficulty":3,"kind":"mc","stem":"일주일은 7일이에요. 3주와 2일은 모두 며칠인가요?","options":[{"t":"23일","correct":true},{"t":"21일","mis":"M2-2-u2-X18"},{"t":"12일","mis":"M2-2-u2-X06"},{"t":"28일","mis":"M2-2-u2-X02"}],"explanation":["3주는 7 × 3 = 21일이에요.","거기에 2일이 더 있어요.","21 + 2 = 23이니 23일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#8','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'essay','teacher','7 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C5","difficulty":4,"kind":"essay","stem":"7 × 6을 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 7 × 5 = 35에 7을 한 번 더 더하면 42이다. 7씩 6줄을 6씩 7줄로 보면 6 × 7 = 42이다.","scoring_points":["7 × 5에 7을 더하는 방법으로 42를 구했는가","6 × 7로 바꾸어 보거나 다른 방법으로 42를 구했는가","7 × 6 = 42라고 썼는가"]},"explanation":["7 × 6은 7 × 5보다 7만큼 커요.","7 × 6과 6 × 7은 곱이 같아요.","어느 방법으로든 42예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#9','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'essay','teacher','로봇이 한 번에 7칸씩 가요. 3번 움직인 로봇이 모두 5번 움직이려면 얼마나 더 가야 하는지 곱셈구구로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C5","difficulty":4,"kind":"essay","stem":"로봇이 한 번에 7칸씩 가요. 3번 움직인 로봇이 모두 5번 움직이려면 얼마나 더 가야 하는지 곱셈구구로 구하고 설명해 보세요.","answer_guide":{"answer":"예: 2번 더 움직여야 하므로 7 × 2 = 14만큼 더 가야 한다. 7 × 3 = 21에 14를 더하면 35 = 7 × 5이다.","scoring_points":["2번 더 움직여야 한다고 썼는가","7 × 2 = 14만큼 더 가야 한다고 구했는가","21 + 14 = 35 = 7 × 5임을 확인했는가"]},"explanation":["5번 − 3번 = 2번 더 움직여요.","한 번에 7칸이니 7 × 2 = 14칸이에요.","7 × 5는 7 × 3과 7 × 2를 더한 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L06_challenge#10','math',2,2,'u2','L06','g2_2_math_u2_L06_challenge','lesson_challenge','M2-2-u2-C5',4,'mc','auto','7단 곱셈구구의 곱 가운데 30보다 크고 50보다 작은 수는 모두 몇 개인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X15']::text[],false,'{"seq":10,"concept":"M2-2-u2-C5","difficulty":4,"kind":"mc","stem":"7단 곱셈구구의 곱 가운데 30보다 크고 50보다 작은 수는 모두 몇 개인가요?","options":[{"t":"3개","correct":true},{"t":"2개","mis":"M2-2-u2-X02"},{"t":"4개","mis":"M2-2-u2-X02"},{"t":"5개","mis":"M2-2-u2-X15"}],"explanation":["7단의 곱은 7, 14, 21, 28, 35, 42, 49, 56, 63이에요.","30보다 크고 50보다 작은 수는 35, 42, 49예요.","그래서 모두 3개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#1','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'sa','auto','9씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C6","difficulty":1,"kind":"sa","stem":"9씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["9씩 커지는 수예요.","27에서 9만큼 더 뛰면 36이에요.","9씩 4번 뛰어 센 수 — 9씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[9],"pmax":45}},"answer":["36"],"asset":{"type":"jump_row","cells":[9,18,27,null],"step":9}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#2','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'sa','auto','9 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C6","difficulty":1,"kind":"sa","stem":"9 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["9 × 3은 9의 3배예요.","9씩 뛰어 세면 9, 18, 27.","그래서 9 × 3 = 27이에요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"answer":["27"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#3','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'mc','auto','상자 한 개에 야구공이 9개씩 있어요. 상자 4개의 야구공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":3,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"상자 한 개에 야구공이 9개씩 있어요. 상자 4개의 야구공은 모두 몇 개인가요?","explanation":["상자 한 개에 9개씩, 4개이면 9씩 4묶음이에요.","9 × 4 = 36이에요.","야구공은 모두 36개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[9]}},"options":[{"t":"36개","correct":true},{"t":"13개","mis":"M2-2-u2-X06"},{"t":"4개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#4','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',1,'mc','auto','9단 곱셈구구에서 곱하는 수가 1 커지면 곱은 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9단 곱셈구구에서 곱하는 수가 1 커지면 곱은 얼마씩 커지나요?","options":[{"t":"9","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"10","mis":"M2-2-u2-X02"}],"explanation":["9단의 곱은 9, 18, 27, 36, …이에요.","곱하는 수가 1 커질 때마다 9를 한 번 더 더해요.","그래서 곱은 9씩 커져요."],"variant_rule":{"alt":[{"stem":"야구공이 한 상자에 9개씩 있어요. 상자가 한 개 늘어나면 야구공은 몇 개 더 많아지나요?","options":[{"t":"9개","correct":true},{"t":"1개","mis":"M2-2-u2-X01"},{"t":"10개","mis":"M2-2-u2-X02"}],"explanation":["상자 한 개에 9개씩이에요.","상자가 하나 늘면 9개가 더 생겨요.","9단 곱셈구구의 곱은 9씩 커져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#5','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'mc','auto','9 × 4 = 36이에요. 이것을 이용하면 9 × 5는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × 4 = 36이에요. 이것을 이용하면 9 × 5는 얼마인가요?","explanation":["9 × 5는 9 × 4보다 9만큼 더 커요.","36 + 9 = 45예요.","한 번 더 더할 때는 곱하는 수 5가 아니라 9를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[9]}},"options":[{"t":"45","correct":true},{"t":"37","mis":"M2-2-u2-X01"},{"t":"41","mis":"M2-2-u2-X17"},{"t":"54","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#6','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'ox','auto','9 × 2부터 9 × 9까지의 곱은 십의 자리 숫자와 일의 자리 숫자를 더하면 9예요.',ARRAY['M2-2-u2-X16']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":2,"kind":"ox","stem":"9 × 2부터 9 × 9까지의 곱은 십의 자리 숫자와 일의 자리 숫자를 더하면 9예요.","answer":"O","reason_options":[{"t":"18, 27, 36처럼 1 + 8, 2 + 7, 3 + 6이 모두 9니까","correct":true},{"t":"곱하는 수가 1씩 커지니까","mis":"M2-2-u2-X16"}],"mis":"M2-2-u2-X16","explanation":["9단의 곱은 18, 27, 36, 45, 54, 63, 72, 81이에요.","두 숫자를 더하면 모두 9예요.","십의 자리는 1씩 커지고 일의 자리는 1씩 작아져요."],"variant_rule":{"alt":[{"stem":"9 × 6의 곱 54는 십의 자리 숫자가 6이에요.","answer":"X","reason_options":[{"t":"54의 십의 자리 숫자는 5니까 — 곱하는 수보다 1 작아요","correct":true},{"t":"곱하는 수와 십의 자리 숫자가 같으니까","mis":"M2-2-u2-X16"}],"explanation":["9 × 6 = 54예요.","십의 자리 숫자는 5, 일의 자리 숫자는 4예요.","9단에서 곱의 십의 자리 숫자는 곱하는 수보다 1 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#7','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"9 × 2","r":"18"},{"l":"9 × 5","r":"45"},{"l":"9 × 7","r":"63"}],"mis":"M2-2-u2-X02","explanation":["9 × 2는 9, 18로 18이에요.","9 × 5는 9씩 5번 뛰어 45예요.","9 × 7은 9씩 7번 뛰어 63이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"9 × 3","r":"27"},{"l":"9 × 6","r":"54"},{"l":"9 × 8","r":"72"}],"explanation":["9 × 3은 9, 18, 27로 27이에요.","9 × 6은 9씩 6번 뛰어 54예요.","9 × 8은 9씩 8번 뛰어 72예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#8','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'mc','auto','9 × □ = 54에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":8,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 54에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 54인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27, 36, 45, 54 — 6번이에요.","9 × 6 = 54라 □는 6이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u2-X02"},{"t":"5","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#9','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',2,'mc','auto','9 × 8은 9 × 7보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":9,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × 8은 9 × 7보다 얼마 더 큰가요?","explanation":["9 × 7은 9를 7번, 9 × 8은 9를 8번 더한 것이에요.","9를 한 번 더 더했으니 9만큼 더 커요 — 63에서 72.","곱하는 수가 1 커지면 곱은 9만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[9]}},"options":[{"t":"9","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_basic#10','math',2,2,'u2','L07','g2_2_math_u2_L07_basic','lesson_basic','M2-2-u2-C6',3,'error','auto','9 × 5를 9 × 2와 9 × 3을 이용해 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C6","difficulty":3,"kind":"error","stem":"9 × 5를 9 × 2와 9 × 3을 이용해 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"서윤 — 「2와 3을 더하면 5니까 9 × 5 = 5야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"도윤 — 「18 + 27 = 45니까 9 × 5 = 45야.」","mis":"M2-2-u2-X15"},{"t":"은솔 — 「9 × 4 = 36에 9를 더해도 45야.」","mis":"M2-2-u2-X15"}],"explanation":["9 × 5는 9 × 2와 9 × 3의 곱을 더한 것과 같아요.","18 + 27 = 45예요.","서윤이는 두 곱 대신 2와 3만 더했어요."],"variant_rule":{"alt":[{"stem":"9 × 6을 9 × 3과 9 × 3을 이용해 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"예린 — 「3과 3을 더하면 6이니까 9 × 6 = 6이야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"태민 — 「27 + 27 = 54니까 9 × 6 = 54야.」","mis":"M2-2-u2-X15"},{"t":"아린 — 「9 × 5 = 45에 9를 더해도 54야.」","mis":"M2-2-u2-X15"}],"explanation":["9 × 6은 9 × 3의 곱을 두 번 더한 것과 같아요.","27 + 27 = 54예요.","예린이는 두 곱 대신 3과 3만 더했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#1','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X03']::text[],true,'{"seq":1,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["9개씩 3묶음이에요.","9의 3배이니 곱셈식으로 9 × 3이에요.","9 × 3 = 27, 모두 27개예요."],"variant_rule":{"mul":{"ask":"expr","ks":[9],"pmax":45}},"options":[{"t":"9 × 3","correct":true},{"t":"9 + 3","mis":"M2-2-u2-X11"},{"t":"9 × 4","mis":"M2-2-u2-X03"}],"asset":{"type":"mul_groups","item":"⚽","k":9,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#2','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',2,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#3','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','곱의 십의 자리 숫자가 4, 일의 자리 숫자가 5인 9단 곱셈구구는 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":3,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"곱의 십의 자리 숫자가 4, 일의 자리 숫자가 5인 9단 곱셈구구는 어느 것인가요?","options":[{"t":"9 × 5","correct":true},{"t":"9 × 4","mis":"M2-2-u2-X16"},{"t":"9 × 6","mis":"M2-2-u2-X16"}],"explanation":["십의 자리 숫자가 4, 일의 자리 숫자가 5인 수는 45예요.","9 × 5 = 45예요.","9 × 4 = 36, 9 × 6 = 54예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#4','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','□ × 7 = 63에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X06']::text[],true,'{"seq":4,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"□ × 7 = 63에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["몇 단 곱셈구구에서 7번째 곱이 63인지 찾아요.","9 × 7 = 63이에요 — 8 × 7 = 56이에요.","그래서 □는 9예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"9","correct":true},{"t":"7","mis":"M2-2-u2-X02"},{"t":"8","mis":"M2-2-u2-X02"},{"t":"56","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#5','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','야구공이 한 상자에 9개씩 7상자 있어요. 그중 2상자를 친구에게 주었어요. 남은 야구공은 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X05','M2-2-u2-X02']::text[],false,'{"seq":5,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"야구공이 한 상자에 9개씩 7상자 있어요. 그중 2상자를 친구에게 주었어요. 남은 야구공은 몇 개인가요?","options":[{"t":"45개","correct":true},{"t":"63개","mis":"M2-2-u2-X18"},{"t":"18개","mis":"M2-2-u2-X05"},{"t":"54개","mis":"M2-2-u2-X02"}],"explanation":["남은 상자는 7 − 2 = 5상자예요.","9 × 5 = 45예요.","63개는 처음에 있던 야구공의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#6','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'mc','auto','9단 곱셈구구의 곱이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9단 곱셈구구의 곱이 아닌 것은 어느 것인가요?","options":[{"t":"56","correct":true},{"t":"54","mis":"M2-2-u2-X15"},{"t":"63","mis":"M2-2-u2-X15"},{"t":"81","mis":"M2-2-u2-X15"}],"explanation":["9단의 곱은 9, 18, 27, 36, 45, 54, 63, 72, 81이에요.","56은 5 + 6 = 11로 두 숫자의 합이 9가 아니에요.","56 = 7 × 8은 7단·8단의 곱이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#7','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',3,'ox','auto','9 × 4의 곱은 9 × 3의 곱보다 1 커요.',ARRAY['M2-2-u2-X01']::text[],false,'{"seq":7,"concept":"M2-2-u2-C6","difficulty":3,"kind":"ox","stem":"9 × 4의 곱은 9 × 3의 곱보다 1 커요.","answer":"X","reason_options":[{"t":"9를 한 번 더 더하니 27에서 36으로 9 커지니까","correct":true},{"t":"곱하는 수가 1 커졌으니 곱도 1 커지니까","mis":"M2-2-u2-X01"}],"mis":"M2-2-u2-X01","explanation":["9 × 3 = 27, 9 × 4 = 36이에요.","36 − 27 = 9예요.","곱하는 수가 1 커지면 9단의 곱은 9씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#8','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'essay','teacher','9 × 5를 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C6","difficulty":4,"kind":"essay","stem":"9 × 5를 두 가지 방법으로 구하고, 각 방법을 설명해 보세요.","answer_guide":{"answer":"예: 9 × 4 = 36에 9를 한 번 더 더하면 45이다. 9 × 2 = 18과 9 × 3 = 27을 더하면 45이다.","scoring_points":["9 × 4에 9를 더하는 방법으로 45를 구했는가","9 × 2와 9 × 3의 곱을 더하는 등 다른 방법으로 45를 구했는가","9 × 5 = 45라고 썼는가"]},"explanation":["9 × 5는 9 × 4보다 9만큼 커요.","9씩 5묶음은 9씩 2묶음과 9씩 3묶음을 합친 것이에요.","두 곱을 더해야지 2와 3을 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#9','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'essay','teacher','9단 곱셈구구의 곱을 모두 쓰고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C6","difficulty":4,"kind":"essay","stem":"9단 곱셈구구의 곱을 모두 쓰고, 곱에서 찾을 수 있는 규칙을 두 가지 써 보세요.","answer_guide":{"answer":"예: 9, 18, 27, 36, 45, 54, 63, 72, 81. 곱이 9씩 커진다. 십의 자리 숫자는 1씩 커지고 일의 자리 숫자는 1씩 작아지며, 두 숫자를 더하면 9이다.","scoring_points":["9단의 곱을 바르게 썼는가","곱이 9씩 커진다는 규칙을 썼는가","십의 자리·일의 자리 숫자의 규칙이나 두 숫자의 합이 9라는 규칙을 썼는가"]},"explanation":["9단의 곱은 9씩 커져요.","십의 자리는 1씩 커지고 일의 자리는 1씩 작아져요.","18부터는 두 숫자의 합이 늘 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L07_challenge#10','math',2,2,'u2','L07','g2_2_math_u2_L07_challenge','lesson_challenge','M2-2-u2-C6',4,'mc','auto','9 × □의 곱은 50보다 크고 60보다 작아요. □에 알맞은 수는 어느 것인가요?',ARRAY['M2-2-u2-X02','M2-2-u2-X05']::text[],false,'{"seq":10,"concept":"M2-2-u2-C6","difficulty":4,"kind":"mc","stem":"9 × □의 곱은 50보다 크고 60보다 작아요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M2-2-u2-X02"},{"t":"7","mis":"M2-2-u2-X02"},{"t":"54","mis":"M2-2-u2-X05"}],"explanation":["9 × 5 = 45, 9 × 6 = 54, 9 × 7 = 63이에요.","50보다 크고 60보다 작은 곱은 54예요.","□는 곱 54가 아니라 곱하는 수 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#1','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'sa','auto','1 × 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C7","difficulty":1,"kind":"sa","stem":"1 × 6은 얼마인가요? 숫자로 쓰세요.","explanation":["1 × 6은 1을 6번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 1 × 6 = 6이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["o1","n1"]}},"answer":["6"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#2','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','0 × 4는 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"0 × 4는 얼마인가요?","explanation":["0 × 4는 0을 4번 더한 것이에요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 0 × 4 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["z0","n0"]}},"options":[{"t":"0","correct":true},{"t":"4","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#3','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','상자 한 개에 인형이 1개씩 들어 있어요. 상자 7개에 든 인형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],true,'{"seq":3,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"상자 한 개에 인형이 1개씩 들어 있어요. 상자 7개에 든 인형은 모두 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"1개","mis":"M2-2-u2-X08"},{"t":"8개","mis":"M2-2-u2-X06"}],"explanation":["상자 한 개에 1개씩, 7상자예요.","1 × 7 = 7이에요.","1을 7번 더하면 7이에요."],"variant_rule":{"alt":[{"stem":"상자 한 개에 인형이 1개씩 들어 있어요. 상자 5개에 든 인형은 모두 몇 개인가요?","options":[{"t":"5개","correct":true},{"t":"1개","mis":"M2-2-u2-X08"},{"t":"6개","mis":"M2-2-u2-X06"}],"explanation":["상자 한 개에 1개씩, 5상자예요.","1 × 5 = 5예요.","1을 5번 더하면 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#4','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',1,'mc','auto','8 × 0은 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":4,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"8 × 0은 얼마인가요?","explanation":["8 × 0은 8을 0번 더한 것 — 하나도 없어요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 8 × 0 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["z0","n0"]}},"options":[{"t":"0","correct":true},{"t":"8","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#5','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'ox','auto','5 × 1 = 1입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":5,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"5 × 1 = 1입니다.","explanation":["5 × 1은 5를 한 번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 5 × 1 = 5예요."],"variant_rule":{"gugu":{"ask":"zero","forms":["o1","n1"]}},"answer":"X","reason_options":[{"t":"5 × 1은 1이 아니라 5가 되니까","correct":true},{"t":"1을 곱하면 1이 되니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#6','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'mc','auto','과녁 맞히기에서 0점에 3번 맞혔어요. 얻은 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":6,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"과녁 맞히기에서 0점에 3번 맞혔어요. 얻은 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"0 × 3 = 0","correct":true},{"t":"0 × 3 = 3","mis":"M2-2-u2-X08"},{"t":"3 × 0 = 3","mis":"M2-2-u2-X08"}],"explanation":["0점을 3번 — 0을 3번 더한 것이에요.","0 + 0 + 0 = 0이에요.","그래서 0 × 3 = 0이에요."],"variant_rule":{"alt":[{"stem":"과녁 맞히기에서 3점에는 한 번도 못 맞혔어요. 3점에서 얻은 점수를 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"3 × 0 = 0","correct":true},{"t":"3 × 0 = 3","mis":"M2-2-u2-X08"},{"t":"0 × 3 = 3","mis":"M2-2-u2-X08"}],"explanation":["3점을 0번 — 한 번도 더하지 않았어요.","그래서 얻은 점수는 0점이에요.","3 × 0 = 0이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#7','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"1 × 6","r":"6"},{"l":"3 × 0","r":"0"},{"l":"1 × 1","r":"1"}],"mis":"M2-2-u2-X08","explanation":["1 × 6은 1을 6번 더한 6이에요.","3 × 0은 3을 한 번도 더하지 않아 0이에요.","1 × 1은 1이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"8 × 1","r":"8"},{"l":"0 × 5","r":"0"},{"l":"1 × 3","r":"3"}],"explanation":["8 × 1은 8을 한 번 더한 8이에요.","0 × 5는 0을 5번 더해 0이에요.","1 × 3은 1을 3번 더한 3이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#8','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'ox','auto','0 × 7 = 0입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":8,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"0 × 7 = 0입니다.","explanation":["0 × 7은 0을 7번 더한 것이에요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 0 × 7 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["z0","n0"]}},"answer":"O","reason_options":[{"t":"0을 7번 더해도 0이니까","correct":true},{"t":"0을 곱하면 그 수가 그대로 남으니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#9','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',2,'ox','auto','1단 곱셈구구의 곱은 1씩 커져요.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":9,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"1단 곱셈구구의 곱은 1씩 커져요.","answer":"O","reason_options":[{"t":"1 × 1 = 1, 1 × 2 = 2, 1 × 3 = 3처럼 1을 한 번씩 더 더하니까","correct":true},{"t":"1을 곱하면 언제나 1이니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08","explanation":["1단의 곱은 1, 2, 3, 4, 5, 6, 7, 8, 9예요.","1을 한 번 더 더할 때마다 1씩 커져요.","1과 어떤 수의 곱은 그 수예요."],"variant_rule":{"alt":[{"stem":"어떤 수에 0을 곱하면 그 수가 그대로예요.","answer":"X","reason_options":[{"t":"0번 더하면 아무것도 없어 0이니까","correct":true},{"t":"0은 아무것도 아니라 곱해도 그대로니까","mis":"M2-2-u2-X08"}],"explanation":["5 × 0은 5를 한 번도 더하지 않은 것이에요.","그래서 0이에요.","어떤 수와 0의 곱은 늘 0이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_basic#10','math',2,2,'u2','L08','g2_2_math_u2_L08_basic','lesson_basic','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 0점에 3번, 1점에 4번, 2점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],true,'{"seq":10,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 0점에 3번, 1점에 4번, 2점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"8점","correct":true},{"t":"11점","mis":"M2-2-u2-X08"},{"t":"9점","mis":"M2-2-u2-X05"}],"explanation":["0 × 3 = 0, 1 × 4 = 4, 2 × 2 = 4예요.","0 + 4 + 4 = 8이에요.","9는 맞힌 횟수를 더한 수예요 — 점수가 아니에요."],"variant_rule":{"alt":[{"stem":"과녁 맞히기에서 0점에 3번, 1점에 2번, 4점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"10점","correct":true},{"t":"13점","mis":"M2-2-u2-X08"},{"t":"7점","mis":"M2-2-u2-X05"}],"explanation":["0 × 3 = 0, 1 × 2 = 2, 4 × 2 = 8이에요.","0 + 2 + 8 = 10이에요.","7은 맞힌 횟수를 더한 수예요 — 점수가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#1','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',2,'sa','auto','9 × 0은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C7","difficulty":2,"kind":"sa","stem":"9 × 0은 얼마인가요? 숫자로 쓰세요.","explanation":["9 × 0은 9를 0번 더한 것 — 하나도 없어요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 9 × 0 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero","forms":["z0","n0"]}},"answer":["0"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#2','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',2,'mc','auto','곱이 다른 하나는 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],false,'{"seq":2,"concept":"M2-2-u2-C7","difficulty":2,"kind":"mc","stem":"곱이 다른 하나는 어느 것인가요?","options":[{"t":"1 × 5","correct":true},{"t":"0 × 5","mis":"M2-2-u2-X15"},{"t":"5 × 0","mis":"M2-2-u2-X15"},{"t":"0 × 9","mis":"M2-2-u2-X15"}],"explanation":["1 × 5 = 5예요.","0 × 5, 5 × 0, 0 × 9는 모두 0이에요.","그래서 곱이 다른 하나는 1 × 5예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#3','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','공 꺼내기 놀이에서 1이 적힌 공을 5번, 0이 적힌 공을 3번 꺼냈어요. 꺼낸 공에 적힌 수만큼 점수를 얻어요. 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X18']::text[],false,'{"seq":3,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"공 꺼내기 놀이에서 1이 적힌 공을 5번, 0이 적힌 공을 3번 꺼냈어요. 꺼낸 공에 적힌 수만큼 점수를 얻어요. 모두 몇 점인가요?","options":[{"t":"5점","correct":true},{"t":"8점","mis":"M2-2-u2-X08"},{"t":"0점","mis":"M2-2-u2-X08"},{"t":"3점","mis":"M2-2-u2-X18"}],"explanation":["1 × 5 = 5, 0 × 3 = 0이에요.","5 + 0 = 5예요.","0이 적힌 공은 몇 번 꺼내도 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#4','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','□ × 6 = 0에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M2-2-u2-X08']::text[],false,'{"seq":4,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"□ × 6 = 0에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"6","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}],"explanation":["곱이 0이 되려면 0을 곱해야 해요.","0 × 6 = 0이에요.","1 × 6 = 6, 6 × 6 = 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#5','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'mc','auto','1 × □ = 8에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],false,'{"seq":5,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"1 × □ = 8에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"8","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"7","mis":"M2-2-u2-X06"}],"explanation":["1과 어떤 수의 곱은 그 수예요.","1 × 8 = 8이에요.","8에서 1을 빼면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#6','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'error','auto','0의 곱에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X15']::text[],false,'{"seq":6,"concept":"M2-2-u2-C7","difficulty":3,"kind":"error","stem":"0의 곱에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「6 × 0은 6이야. 6이 그대로 있으니까.」","correct":true,"mis_target":"M2-2-u2-X08"},{"t":"서윤 — 「0 × 6은 0이야.」","mis":"M2-2-u2-X15"},{"t":"준우 — 「6을 한 번도 더하지 않으면 0이야.」","mis":"M2-2-u2-X15"}],"explanation":["6 × 0은 6을 한 번도 더하지 않은 것이에요.","그래서 0이에요.","하람이의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#7','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',3,'ox','auto','1 × 9와 9 × 1은 곱이 같아요.',ARRAY['M2-2-u2-X08']::text[],false,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":3,"kind":"ox","stem":"1 × 9와 9 × 1은 곱이 같아요.","answer":"O","reason_options":[{"t":"둘 다 9니까 — 두 수를 바꾸어 곱해도 곱이 같아요","correct":true},{"t":"1을 곱하면 언제나 1이 되니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08","explanation":["1 × 9는 1을 9번 더한 9예요.","9 × 1은 9를 한 번 더한 9예요.","그래서 곱이 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#8','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'essay','teacher','과녁 맞히기에서 0점에 2번, 1점에 3번 맞혔고 3점에는 한 번도 못 맞혔어요. 점수마다 곱셈식으로 나타내 구하고, 모두 몇 점인지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C7","difficulty":4,"kind":"essay","stem":"과녁 맞히기에서 0점에 2번, 1점에 3번 맞혔고 3점에는 한 번도 못 맞혔어요. 점수마다 곱셈식으로 나타내 구하고, 모두 몇 점인지 써 보세요.","answer_guide":{"answer":"예: 0 × 2 = 0, 1 × 3 = 3, 3 × 0 = 0이다. 0 + 3 + 0 = 3이므로 모두 3점이다.","scoring_points":["0 × 2 = 0을 썼는가","1 × 3 = 3과 3 × 0 = 0을 썼는가","모두 3점이라고 구했는가"]},"explanation":["맞힌 점수 × 맞힌 횟수로 써요.","0점은 몇 번 맞혀도 0, 한 번도 못 맞힌 점수도 0이에요.","0 + 3 + 0 = 3점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#9','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'essay','teacher','0 × 4와 4 × 0이 모두 0인 까닭을 덧셈을 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C7","difficulty":4,"kind":"essay","stem":"0 × 4와 4 × 0이 모두 0인 까닭을 덧셈을 써서 설명해 보세요.","answer_guide":{"answer":"예: 0 × 4는 0을 4번 더한 것으로 0 + 0 + 0 + 0 = 0이다. 4 × 0은 4를 한 번도 더하지 않은 것이므로 0이다.","scoring_points":["0 × 4를 0을 4번 더한 것으로 설명했는가","4 × 0을 4를 한 번도 더하지 않은 것으로 설명했는가","둘 다 0이라고 썼는가"]},"explanation":["0을 여러 번 더해도 0이에요.","어떤 수를 0번 더하면 아무것도 없어요.","그래서 0과 어떤 수의 곱, 어떤 수와 0의 곱은 0이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L08_challenge#10','math',2,2,'u2','L08','g2_2_math_u2_L08_challenge','lesson_challenge','M2-2-u2-C7',4,'mc','auto','지호는 1점짜리 문제를 7개, 0점짜리 문제를 2개 맞혔어요. 하린이는 1점짜리 문제를 5개 맞혔어요. 지호는 하린이보다 몇 점 더 얻었나요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05','M2-2-u2-X06']::text[],false,'{"seq":10,"concept":"M2-2-u2-C7","difficulty":4,"kind":"mc","stem":"지호는 1점짜리 문제를 7개, 0점짜리 문제를 2개 맞혔어요. 하린이는 1점짜리 문제를 5개 맞혔어요. 지호는 하린이보다 몇 점 더 얻었나요?","options":[{"t":"2점","correct":true},{"t":"4점","mis":"M2-2-u2-X08"},{"t":"7점","mis":"M2-2-u2-X05"},{"t":"12점","mis":"M2-2-u2-X06"}],"explanation":["지호는 1 × 7 + 0 × 2 = 7점이에요.","하린이는 1 × 5 = 5점이에요.","7 − 5 = 2이니 2점 더 얻었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#1','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":1,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 3과 위쪽 4가 만나는 칸이에요.","그래서 3 × 4의 곱을 써요 — 3 × 3 = 9에 3을 더해도 돼요.","3 × 4 = 12예요."],"variant_rule":{"gugu":{"ask":"cell","ks":[2,3,4,5]}},"options":[{"t":"12","correct":true},{"t":"15","mis":"M2-2-u2-X09"},{"t":"9","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[3,4,5,6],"cols":[1,2,3,4,5],"q":[3,4],"blank":[[5,4],[3,5]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#2','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'sa','auto','곱셈표의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C8","difficulty":1,"kind":"sa","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["?는 왼쪽 5와 위쪽 6이 만나는 칸이에요.","그래서 5 × 6의 곱을 써요 — 5 × 5 = 25에 5를 더해도 돼요.","5 × 6 = 30이에요."],"variant_rule":{"gugu":{"ask":"cell","ks":[2,3,4,5]}},"answer":["30"],"asset":{"type":"gugu_table","rows":[4,5,6,7],"cols":[5,6,7,8,9],"q":[5,6],"blank":[[5,5],[7,6]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#3','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','곱셈표에서 색칠한 4단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":3,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표에서 색칠한 4단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["4단의 곱은 4, 8, 12, …예요.","곱하는 수가 1 커질 때마다 4씩 커져요.","그래서 4단 곱셈구구의 곱은 4씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"4","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"5","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[2,3,4],"cols":[1,2,3,4,5,6,7,8,9],"hrow":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#4','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',1,'mc','auto','4 × 7과 곱이 같은 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],true,'{"seq":4,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"4 × 7과 곱이 같은 곱셈식은 어느 것인가요?","explanation":["4 × 7은 4씩 7묶음, 7 × 4는 7씩 4묶음이에요.","같은 28개를 가로로 묶느냐 세로로 묶느냐의 차이예요.","그래서 4 × 7과 7 × 4의 곱은 28로 같아요."],"variant_rule":{"mul":{"ask":"same","pmax":81}},"options":[{"t":"7 × 4","correct":true},{"t":"4 × 4","mis":"M2-2-u2-X13"},{"t":"7 × 7","mis":"M2-2-u2-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#5','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":5,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 7과 위쪽 6이 만나는 칸이에요.","그래서 7 × 6의 곱을 써요 — 7 × 5 = 35에 7을 더해도 돼요.","7 × 6 = 42예요."],"variant_rule":{"gugu":{"ask":"cell","ks":[6,7,8,9]}},"options":[{"t":"42","correct":true},{"t":"49","mis":"M2-2-u2-X09"},{"t":"35","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[4,5,6,7],"cols":[4,5,6,7,8],"q":[7,6],"blank":[[7,7],[6,6]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#6','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'ox','auto','곱셈표를 같은 수끼리 만나는 칸을 이은 점선을 따라 접으면 만나는 수가 서로 같아요.',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":6,"concept":"M2-2-u2-C8","difficulty":2,"kind":"ox","stem":"곱셈표를 같은 수끼리 만나는 칸을 이은 점선을 따라 접으면 만나는 수가 서로 같아요.","answer":"O","reason_options":[{"t":"3 × 5와 5 × 3처럼 두 수를 바꾸어 곱한 칸끼리 만나니까","correct":true},{"t":"접으면 늘 같은 단끼리 만나니까","mis":"M2-2-u2-X09"}],"mis":"M2-2-u2-X09","explanation":["점선은 1 × 1, 2 × 2, 3 × 3, …처럼 같은 수끼리 만나는 칸이에요.","접으면 4 × 6과 6 × 4처럼 두 수를 바꾼 칸이 만나요.","두 수를 바꾸어 곱해도 곱이 같으니 만나는 수가 같아요."],"asset":{"type":"gugu_table","rows":[1,2,3,4,5,6],"cols":[1,2,3,4,5,6],"diag":true},"variant_rule":{"alt":[{"stem":"곱셈표에서 6단 곱셈구구의 곱은 오른쪽으로 갈수록 6씩 커져요.","answer":"O","reason_options":[{"t":"6단은 6을 한 번씩 더 더하니까","correct":true},{"t":"곱셈표의 수는 오른쪽으로 갈 때 1씩 커지니까","mis":"M2-2-u2-X01"}],"explanation":["6단의 곱은 6, 12, 18, 24, …예요.","오른쪽으로 한 칸 가면 곱하는 수가 1 커져요.","그래서 곱은 6씩 커져요."],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[1,2,3,4,5,6,7,8,9],"hrow":6}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#7','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 24인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":7,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 24인 것은 모두 몇 개인가요?","explanation":["곱이 24인 곱셈구구는 3 × 8, 4 × 6, 6 × 4, 8 × 3이에요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u2-X13"},{"t":"5","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#8','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱이 24인 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-2-u2-X15']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱이 24인 곱셈식이 아닌 것은 어느 것인가요?","explanation":["5 × 5 = 25예요.","나머지 곱셈식의 곱은 모두 24예요.","「아닌 것」을 묻는지 다시 읽어요 — 같은 수도 여러 곱셈식으로 나타낼 수 있어요."],"variant_rule":{"mul":{"ask":"notx","pmax":81}},"options":[{"t":"5 × 5","correct":true},{"t":"8 × 3","mis":"M2-2-u2-X15"},{"t":"6 × 4","mis":"M2-2-u2-X15"},{"t":"3 × 8","mis":"M2-2-u2-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#9','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',2,'mc','auto','곱셈표에서 곱이 16인 곱셈구구를 모두 찾은 것은 어느 것인가요?',ARRAY['M2-2-u2-X13']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 곱이 16인 곱셈구구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"2 × 8, 4 × 4, 8 × 2","correct":true},{"t":"4 × 4","mis":"M2-2-u2-X13"},{"t":"2 × 8, 8 × 2","mis":"M2-2-u2-X13"}],"explanation":["곱이 16인 칸은 2단, 4단, 8단에 있어요.","2 × 8 = 16, 4 × 4 = 16, 8 × 2 = 16이에요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."],"variant_rule":{"alt":[{"stem":"곱셈표에서 곱이 9인 곱셈구구를 모두 찾은 것은 어느 것인가요?","options":[{"t":"1 × 9, 3 × 3, 9 × 1","correct":true},{"t":"3 × 3","mis":"M2-2-u2-X13"},{"t":"1 × 9, 9 × 1","mis":"M2-2-u2-X13"}],"explanation":["곱이 9인 칸은 1단, 3단, 9단에 있어요.","1 × 9 = 9, 3 × 3 = 9, 9 × 1 = 9예요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_basic#10','math',2,2,'u2','L09','g2_2_math_u2_L09_basic','lesson_basic','M2-2-u2-C8',3,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":10,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 8과 위쪽 7이 만나는 칸이에요.","그래서 8 × 7의 곱을 써요 — 8 × 6 = 48에 8을 더해도 돼요.","8 × 7 = 56이에요."],"variant_rule":{"gugu":{"ask":"cell","ks":[6,7,8,9]}},"options":[{"t":"56","correct":true},{"t":"64","mis":"M2-2-u2-X09"},{"t":"48","mis":"M2-2-u2-X09"},{"t":"63","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[6,7,8,9],"cols":[5,6,7,8,9],"q":[8,7],"blank":[[8,8],[7,7]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#1','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 7단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":1,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 7단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["7단의 곱은 7, 14, 21, …예요.","곱하는 수가 1 커질 때마다 7씩 커져요.","그래서 7단 곱셈구구의 곱은 7씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[6,7,8],"cols":[1,2,3,4,5,6,7,8,9],"hrow":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#2','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',2,'sa','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 12인 것은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C8","difficulty":2,"kind":"sa","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 12인 것은 모두 몇 개인가요? 숫자로 쓰세요.","explanation":["곱이 12인 곱셈구구는 2 × 6, 3 × 4, 4 × 3, 6 × 2예요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"answer":["4"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#3','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09','M2-2-u2-X11']::text[],true,'{"seq":3,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 9와 위쪽 8이 만나는 칸이에요.","그래서 9 × 8의 곱을 써요 — 9 × 7 = 63에 9를 더해도 돼요.","9 × 8 = 72예요."],"variant_rule":{"gugu":{"ask":"cell","ks":[6,7,8,9]}},"options":[{"t":"72","correct":true},{"t":"81","mis":"M2-2-u2-X09"},{"t":"63","mis":"M2-2-u2-X09"},{"t":"17","mis":"M2-2-u2-X11"}],"asset":{"type":"gugu_table","rows":[6,7,8,9],"cols":[5,6,7,8,9],"q":[9,8],"blank":[[9,5],[7,8]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#4','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표의 5단 줄에서 5 × 1부터 5 × 9까지의 곱 가운데 일의 자리 숫자가 0인 칸은 모두 몇 개인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":4,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 5단 줄에서 5 × 1부터 5 × 9까지의 곱 가운데 일의 자리 숫자가 0인 칸은 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"5개","mis":"M2-2-u2-X16"},{"t":"9개","mis":"M2-2-u2-X16"}],"explanation":["5단의 곱은 5, 10, 15, 20, 25, 30, 35, 40, 45예요.","일의 자리 숫자가 0인 것은 10, 20, 30, 40이에요.","그래서 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#5','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표에서 3 × 8과 곱이 같은 곱셈구구를 모두 찾은 친구는 누구인가요?',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":5,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표에서 3 × 8과 곱이 같은 곱셈구구를 모두 찾은 친구는 누구인가요?","options":[{"t":"지안 — 「8 × 3, 4 × 6, 6 × 4」","correct":true},{"t":"아린 — 「8 × 3」","mis":"M2-2-u2-X13"},{"t":"태민 — 「8 × 3, 4 × 6」","mis":"M2-2-u2-X13"}],"explanation":["3 × 8 = 24예요.","곱이 24인 칸은 8 × 3, 4 × 6, 6 × 4에도 있어요.","두 수를 바꾼 것과 다른 단의 곱까지 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#6','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','곱셈표의 같은 가로줄에서 이웃한 두 칸이 35와 42예요. 몇 단의 줄인가요?',ARRAY['M2-2-u2-X09']::text[],false,'{"seq":6,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"곱셈표의 같은 가로줄에서 이웃한 두 칸이 35와 42예요. 몇 단의 줄인가요?","options":[{"t":"7단","correct":true},{"t":"5단","mis":"M2-2-u2-X09"},{"t":"6단","mis":"M2-2-u2-X09"}],"explanation":["이웃한 칸의 곱은 그 단의 수만큼 커져요.","42 − 35 = 7이에요.","35 = 7 × 5, 42 = 7 × 6 — 7단의 줄이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#7','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',3,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 36인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":7,"concept":"M2-2-u2-C8","difficulty":3,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 36인 것은 모두 몇 개인가요?","explanation":["곱이 36인 곱셈구구는 4 × 9, 6 × 6, 9 × 4예요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 3개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"3","correct":true},{"t":"2","mis":"M2-2-u2-X13"},{"t":"4","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#8','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 4 × 6과 곱이 같은 곱셈구구를 모두 찾고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 4 × 6과 곱이 같은 곱셈구구를 모두 찾고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 4 × 6 = 24이다. 곱셈표에서 24가 있는 칸을 찾으면 6 × 4, 3 × 8, 8 × 3이 있다. 두 수를 바꾸어 곱해도 곱이 같고, 다른 단에도 24가 있다.","scoring_points":["4 × 6 = 24를 구했는가","6 × 4, 3 × 8, 8 × 3을 모두 찾았는가","곱셈표에서 24인 칸을 찾았다고 방법을 썼는가"]},"explanation":["4 × 6 = 24예요.","곱셈표에서 24는 3단, 4단, 6단, 8단에 있어요.","6 × 4만 찾으면 3 × 8, 8 × 3을 놓쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#9','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'essay','teacher','곱셈표의 6 × 5 칸이 비어 있어요. 바로 왼쪽 칸 6 × 4 = 24를 이용하는 방법과 5 × 6을 이용하는 방법으로 빈칸을 채우고 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표의 6 × 5 칸이 비어 있어요. 바로 왼쪽 칸 6 × 4 = 24를 이용하는 방법과 5 × 6을 이용하는 방법으로 빈칸을 채우고 설명해 보세요.","answer_guide":{"answer":"예: 6 × 5는 6 × 4보다 6 크므로 24 + 6 = 30이다. 6 × 5와 5 × 6은 곱이 같으므로 5단에서 5 × 6 = 30을 찾아도 30이다.","scoring_points":["6 × 4에 6을 더해 30을 구했는가","5 × 6과 곱이 같음을 이용해 30을 구했는가","빈칸에 30을 썼는가"]},"explanation":["곱셈표에서 오른쪽으로 한 칸 가면 그 단의 수만큼 커져요.","두 수를 바꾸어 곱해도 곱이 같아요.","두 방법 모두 30이에요."],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[3,4,5,6],"blank":[[6,5]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L09_challenge#10','math',2,2,'u2','L09','g2_2_math_u2_L09_challenge','lesson_challenge','M2-2-u2-C8',4,'mc','auto','1단부터 9단까지의 곱셈표에서 곱이 8인 칸과 곱이 9인 칸은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],false,'{"seq":10,"concept":"M2-2-u2-C8","difficulty":4,"kind":"mc","stem":"1단부터 9단까지의 곱셈표에서 곱이 8인 칸과 곱이 9인 칸은 모두 몇 개인가요?","options":[{"t":"7개","correct":true},{"t":"4개","mis":"M2-2-u2-X13"},{"t":"6개","mis":"M2-2-u2-X13"},{"t":"8개","mis":"M2-2-u2-X09"}],"explanation":["곱이 8인 칸: 1 × 8, 2 × 4, 4 × 2, 8 × 1 — 4개예요.","곱이 9인 칸: 1 × 9, 3 × 3, 9 × 1 — 3개예요.","4 + 3 = 7이니 모두 7개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#1','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','해마가 한 줄에 5마리씩 3줄 있어요. 해마는 모두 몇 마리인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X03']::text[],true,'{"seq":1,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"해마가 한 줄에 5마리씩 3줄 있어요. 해마는 모두 몇 마리인가요?","options":[{"t":"15마리","correct":true},{"t":"8마리","mis":"M2-2-u2-X06"},{"t":"20마리","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 5마리씩, 3줄이에요.","5 × 3 = 15예요.","하나씩 세지 않고 곱셈구구로 빠르게 구했어요."],"variant_rule":{"alt":[{"stem":"해마가 한 줄에 6마리씩 4줄 있어요. 해마는 모두 몇 마리인가요?","options":[{"t":"24마리","correct":true},{"t":"10마리","mis":"M2-2-u2-X06"},{"t":"30마리","mis":"M2-2-u2-X03"}],"explanation":["한 줄에 6마리씩, 4줄이에요.","6 × 4 = 24예요.","하나씩 세지 않고 곱셈구구로 빠르게 구했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#2','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','로봇이 한 줄에 8대씩 2줄 있어요. 로봇의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X04']::text[],true,'{"seq":2,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"로봇이 한 줄에 8대씩 2줄 있어요. 로봇의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"8 × 2","correct":true},{"t":"8 + 2","mis":"M2-2-u2-X11"},{"t":"2 × 2","mis":"M2-2-u2-X04"}],"explanation":["한 줄에 8대씩 — 한 묶음은 8이에요.","2줄이니 8 × 2예요.","8 × 2 = 16이니 로봇은 16대예요."],"variant_rule":{"alt":[{"stem":"로봇이 한 줄에 7대씩 3줄 있어요. 로봇의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"7 × 3","correct":true},{"t":"7 + 3","mis":"M2-2-u2-X11"},{"t":"3 × 3","mis":"M2-2-u2-X04"}],"explanation":["한 줄에 7대씩 — 한 묶음은 7이에요.","3줄이니 7 × 3이에요.","7 × 3 = 21이니 로봇은 21대예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#3','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'mc','auto','필통 한 개에 연필이 6자루씩 있어요. 필통 5개의 연필 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X14']::text[],true,'{"seq":3,"concept":"M2-2-u2-C9","difficulty":1,"kind":"mc","stem":"필통 한 개에 연필이 6자루씩 있어요. 필통 5개의 연필 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 개에 6자루씩 — 한 묶음은 6이에요.","필통이 5개이니 6씩 5묶음, 6의 5배예요.","곱셈식은 6 × 5 = 30이에요."],"variant_rule":{"mul":{"ask":"sexpr","pmax":81,"per":[4,6,8]}},"options":[{"t":"6 × 5","correct":true},{"t":"6 + 5","mis":"M2-2-u2-X11"},{"t":"6 × 6","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#4','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',1,'sa','auto','거미 한 마리에 다리가 8개씩 있어요. 거미 4마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-2-u2-C9","difficulty":1,"kind":"sa","stem":"거미 한 마리에 다리가 8개씩 있어요. 거미 4마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.","explanation":["거미 한 마리에 8개씩, 4마리이면 8씩 4묶음이에요.","8 × 4 = 32예요.","다리는 모두 32개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[4,6,8]}},"answer":["32","32개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#5','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','책상이 한 줄에 5개씩 4줄로 놓여 있는데, 한 자리가 비어 있어요. 책상은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],true,'{"seq":5,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"책상이 한 줄에 5개씩 4줄로 놓여 있는데, 한 자리가 비어 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"19개","correct":true},{"t":"20개","mis":"M2-2-u2-X18"},{"t":"9개","mis":"M2-2-u2-X06"}],"explanation":["빈자리까지 채우면 5 × 4 = 20개예요.","한 자리가 비었으니 20 − 1 = 19예요.","빈자리를 빼는 것을 잊지 않아요."],"variant_rule":{"alt":[{"stem":"책상이 한 줄에 6개씩 3줄로 놓여 있는데, 두 자리가 비어 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"16개","correct":true},{"t":"18개","mis":"M2-2-u2-X18"},{"t":"9개","mis":"M2-2-u2-X06"}],"explanation":["빈자리까지 채우면 6 × 3 = 18개예요.","두 자리가 비었으니 18 − 2 = 16이에요.","빈자리를 빼는 것을 잊지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#6','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','사탕이 한 봉지에 6개씩 3봉지 있고, 낱개로 2개가 더 있어요. 사탕은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],true,'{"seq":6,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"사탕이 한 봉지에 6개씩 3봉지 있고, 낱개로 2개가 더 있어요. 사탕은 모두 몇 개인가요?","options":[{"t":"20개","correct":true},{"t":"18개","mis":"M2-2-u2-X18"},{"t":"11개","mis":"M2-2-u2-X06"}],"explanation":["봉지에 든 사탕은 6 × 3 = 18개예요.","낱개 2개를 더해요.","18 + 2 = 20이니 모두 20개예요."],"variant_rule":{"alt":[{"stem":"구슬이 한 주머니에 4개씩 5주머니 있고, 낱개로 3개가 더 있어요. 구슬은 모두 몇 개인가요?","options":[{"t":"23개","correct":true},{"t":"20개","mis":"M2-2-u2-X18"},{"t":"12개","mis":"M2-2-u2-X06"}],"explanation":["주머니에 든 구슬은 4 × 5 = 20개예요.","낱개 3개를 더해요.","20 + 3 = 23이니 모두 23개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#7','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'match','auto','상황과 곱셈식을 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M2-2-u2-C9","difficulty":2,"kind":"match","stem":"상황과 곱셈식을 이으세요.","pairs":[{"l":"자동차 3대의 바퀴","r":"4 × 3"},{"l":"세발자전거 4대의 바퀴","r":"3 × 4"},{"l":"거미 2마리의 다리","r":"8 × 2"}],"mis":"M2-2-u2-X14","explanation":["자동차 한 대에 바퀴 4개씩, 3대 → 4 × 3","세발자전거 한 대에 바퀴 3개씩, 4대 → 3 × 4","거미 한 마리에 다리 8개씩, 2마리 → 8 × 2"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황과 곱셈식을 이으세요.","pairs":[{"l":"문어 3마리의 다리","r":"8 × 3"},{"l":"개미 4마리의 다리","r":"6 × 4"},{"l":"오리 5마리의 다리","r":"2 × 5"}],"explanation":["문어 한 마리에 다리 8개씩, 3마리 → 8 × 3","개미 한 마리에 다리 6개씩, 4마리 → 6 × 4","오리 한 마리에 다리 2개씩, 5마리 → 2 × 5"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#8','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','연결 모형이 왼쪽에 3개씩 2줄, 오른쪽에 5개씩 4줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X18']::text[],true,'{"seq":8,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"연결 모형이 왼쪽에 3개씩 2줄, 오른쪽에 5개씩 4줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"26개","correct":true},{"t":"14개","mis":"M2-2-u2-X17"},{"t":"20개","mis":"M2-2-u2-X18"}],"explanation":["왼쪽은 3 × 2 = 6개예요.","오른쪽은 5 × 4 = 20개예요.","6 + 20 = 26이니 모두 26개예요."],"variant_rule":{"alt":[{"stem":"연결 모형이 왼쪽에 2개씩 4줄, 오른쪽에 6개씩 3줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"26개","correct":true},{"t":"15개","mis":"M2-2-u2-X17"},{"t":"18개","mis":"M2-2-u2-X18"}],"explanation":["왼쪽은 2 × 4 = 8개예요.","오른쪽은 6 × 3 = 18개예요.","8 + 18 = 26이니 모두 26개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#9','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',2,'mc','auto','주머니 한 개에 구슬이 7개씩 있어요. 주머니 4개의 구슬은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":9,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"주머니 한 개에 구슬이 7개씩 있어요. 주머니 4개의 구슬은 모두 몇 개인가요?","explanation":["주머니 한 개에 7개씩, 4개이면 7씩 4묶음이에요.","7 × 4 = 28이에요.","구슬은 모두 28개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81,"per":[3,5,7,9]}},"options":[{"t":"28개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"4개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_basic#10','math',2,2,'u2','L10','g2_2_math_u2_L10_basic','lesson_basic','M2-2-u2-C9',3,'error','auto','의자가 한 줄에 4개씩 5줄로 놓여 있는데 한 자리에 의자가 없어요. 의자의 수를 잘못 구한 친구는 누구인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X15']::text[],true,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":3,"kind":"error","stem":"의자가 한 줄에 4개씩 5줄로 놓여 있는데 한 자리에 의자가 없어요. 의자의 수를 잘못 구한 친구는 누구인가요?","options":[{"t":"곰이 — 「4 × 5 = 20이니까 20개야.」","correct":true,"mis_target":"M2-2-u2-X18"},{"t":"펭이 — 「4 × 5 = 20에서 1을 빼면 19개야.」","mis":"M2-2-u2-X15"},{"t":"다예 — 「4 × 4 = 16에 3을 더하면 19개야.」","mis":"M2-2-u2-X15"}],"explanation":["빈자리까지 채우면 4 × 5 = 20개예요.","빈자리 하나를 빼면 19개예요.","곰이는 빈자리를 빼지 않았어요."],"variant_rule":{"alt":[{"stem":"의자가 한 줄에 6개씩 4줄로 놓여 있는데 두 자리에 의자가 없어요. 의자의 수를 잘못 구한 친구는 누구인가요?","options":[{"t":"지우 — 「6 × 4 = 24이니까 24개야.」","correct":true,"mis_target":"M2-2-u2-X18"},{"t":"서아 — 「6 × 4 = 24에서 2를 빼면 22개야.」","mis":"M2-2-u2-X15"},{"t":"하루 — 「6 × 3 = 18에 4를 더하면 22개야.」","mis":"M2-2-u2-X15"}],"explanation":["빈자리까지 채우면 6 × 4 = 24개예요.","빈자리 둘을 빼면 22개예요.","지우는 빈자리를 빼지 않았어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#1','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',2,'mc','auto','야구공이 한 상자에 9개씩 2상자, 테니스공이 한 상자에 6개씩 3상자 있어요. 공은 모두 몇 개인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X18']::text[],false,'{"seq":1,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"야구공이 한 상자에 9개씩 2상자, 테니스공이 한 상자에 6개씩 3상자 있어요. 공은 모두 몇 개인가요?","options":[{"t":"36개","correct":true},{"t":"20개","mis":"M2-2-u2-X17"},{"t":"18개","mis":"M2-2-u2-X18"}],"explanation":["야구공은 9 × 2 = 18개예요.","테니스공은 6 × 3 = 18개예요.","18 + 18 = 36이니 모두 36개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#2','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',2,'mc','auto','문어 한 마리에 다리가 8개씩 있어요. 문어 6마리의 다리 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X14']::text[],true,'{"seq":2,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"문어 한 마리에 다리가 8개씩 있어요. 문어 6마리의 다리 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 마리에 8개씩 — 한 묶음은 8이에요.","문어가 6마리이니 8씩 6묶음, 8의 6배예요.","곱셈식은 8 × 6 = 48이에요."],"variant_rule":{"mul":{"ask":"sexpr","pmax":81,"per":[6,8]}},"options":[{"t":"8 × 6","correct":true},{"t":"8 + 6","mis":"M2-2-u2-X11"},{"t":"8 × 8","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#3','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','꽃잎이 5장인 꽃이 6송이, 꽃잎이 4장인 꽃이 3송이 있어요. 꽃잎은 모두 몇 장인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X17','M2-2-u2-X02']::text[],false,'{"seq":3,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"꽃잎이 5장인 꽃이 6송이, 꽃잎이 4장인 꽃이 3송이 있어요. 꽃잎은 모두 몇 장인가요?","options":[{"t":"42장","correct":true},{"t":"30장","mis":"M2-2-u2-X18"},{"t":"18장","mis":"M2-2-u2-X17"},{"t":"36장","mis":"M2-2-u2-X02"}],"explanation":["꽃잎이 5장인 꽃은 5 × 6 = 30장이에요.","꽃잎이 4장인 꽃은 4 × 3 = 12장이에요.","30 + 12 = 42이니 모두 42장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#4','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','연필이 한 묶음에 6자루씩 4묶음 있어요. 친구 3명에게 2자루씩 나누어 주면 남는 연필은 몇 자루인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":4,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"연필이 한 묶음에 6자루씩 4묶음 있어요. 친구 3명에게 2자루씩 나누어 주면 남는 연필은 몇 자루인가요?","options":[{"t":"18자루","correct":true},{"t":"24자루","mis":"M2-2-u2-X18"},{"t":"22자루","mis":"M2-2-u2-X06"},{"t":"19자루","mis":"M2-2-u2-X06"}],"explanation":["연필은 6 × 4 = 24자루예요.","나누어 준 연필은 2 × 3 = 6자루예요.","24 − 6 = 18이니 18자루가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#5','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','닭 3마리와 강아지 4마리가 있어요. 다리는 모두 몇 개인가요?',ARRAY['M2-2-u2-X14','M2-2-u2-X05']::text[],false,'{"seq":5,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"닭 3마리와 강아지 4마리가 있어요. 다리는 모두 몇 개인가요?","options":[{"t":"22개","correct":true},{"t":"28개","mis":"M2-2-u2-X14"},{"t":"14개","mis":"M2-2-u2-X14"},{"t":"7개","mis":"M2-2-u2-X05"}],"explanation":["닭의 다리는 2 × 3 = 6개예요.","강아지의 다리는 4 × 4 = 16개예요.","6 + 16 = 22이니 모두 22개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#6','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#7','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',3,'mc','auto','색종이가 한 봉투에 4장씩 들어 있어요. 색종이 32장을 모두 담으려면 봉투가 몇 개 있어야 하나요?',ARRAY['M2-2-u2-X06','M2-2-u2-X02']::text[],false,'{"seq":7,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"색종이가 한 봉투에 4장씩 들어 있어요. 색종이 32장을 모두 담으려면 봉투가 몇 개 있어야 하나요?","options":[{"t":"8개","correct":true},{"t":"28개","mis":"M2-2-u2-X06"},{"t":"7개","mis":"M2-2-u2-X02"},{"t":"9개","mis":"M2-2-u2-X02"}],"explanation":["4단 곱셈구구에서 곱이 32인 것을 찾아요.","4 × 8 = 32예요.","그래서 봉투가 8개 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#8','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'essay','teacher','책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상의 수를 두 가지 방법으로 구하고 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"책상이 한 줄에 4개씩 5줄로 놓여 있는데 한 자리가 비어 있어요. 책상의 수를 두 가지 방법으로 구하고 설명해 보세요.","answer_guide":{"answer":"예: 빈자리까지 채우면 4 × 5 = 20개이고 빈자리 1개를 빼면 19개이다. 꽉 찬 4줄은 4 × 4 = 16개이고 남은 줄의 3개를 더하면 19개이다.","scoring_points":["4 × 5에서 1을 빼는 방법으로 19를 구했는가","4 × 4에 3을 더하는 등 다른 방법으로 19를 구했는가","책상이 19개라고 썼는가"]},"explanation":["빈자리까지 채워 곱한 뒤 빈자리를 빼요.","꽉 찬 줄과 덜 찬 줄을 나누어 구한 뒤 더해도 돼요.","두 방법 모두 19개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#9','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'essay','teacher','우리 반 사물함이나 학용품처럼 곱셈구구로 수를 구할 수 있는 상황을 하나 만들고, 곱셈식으로 해결해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"우리 반 사물함이나 학용품처럼 곱셈구구로 수를 구할 수 있는 상황을 하나 만들고, 곱셈식으로 해결해 보세요.","answer_guide":{"answer":"예: 사물함이 한 줄에 6칸씩 4줄 있다. 사물함은 6 × 4 = 24칸이다.","scoring_points":["같은 수씩 여러 묶음이 있는 상황을 만들었는가","한 묶음의 수와 묶음의 수로 곱셈식을 바르게 썼는가","곱을 바르게 구했는가"]},"explanation":["「한 줄에 몇 개씩」 놓인 것을 찾아요.","한 묶음의 수 × 묶음의 수로 써요.","곱셈구구로 곱을 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_L10_challenge#10','math',2,2,'u2','L10','g2_2_math_u2_L10_challenge','lesson_challenge','M2-2-u2-C9',4,'mc','auto','사과가 한 상자에 8개씩 3상자, 귤이 한 봉지에 7개씩 4봉지 있어요. 귤은 사과보다 몇 개 더 많은가요?',ARRAY['M2-2-u2-X15','M2-2-u2-X19','M2-2-u2-X02']::text[],false,'{"seq":10,"concept":"M2-2-u2-C9","difficulty":4,"kind":"mc","stem":"사과가 한 상자에 8개씩 3상자, 귤이 한 봉지에 7개씩 4봉지 있어요. 귤은 사과보다 몇 개 더 많은가요?","options":[{"t":"4개","correct":true},{"t":"52개","mis":"M2-2-u2-X15"},{"t":"1개","mis":"M2-2-u2-X19"},{"t":"5개","mis":"M2-2-u2-X02"}],"explanation":["사과는 8 × 3 = 24개예요.","귤은 7 × 4 = 28개예요.","28 − 24 = 4이니 귤이 4개 더 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#1','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","6에서 2만큼 더 뛰면 8이에요.","2씩 4번 뛰어 센 수 — 2씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["8"],"asset":{"type":"jump_row","cells":[2,4,6,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#2','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C2',1,'sa','auto','5 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 3은 5의 3배예요.","5씩 뛰어 세면 5, 10, 15.","그래서 5 × 3 = 15예요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#3','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C3',1,'sa','auto','3 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"3 × 7은 얼마인가요? 숫자로 쓰세요.","explanation":["3 × 7은 3의 7배예요.","3씩 뛰어 세면 3, 6, 9, 12, 15, 18, 21.","그래서 3 × 7 = 21이에요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["21"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#4','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',1,'mc','auto','4 × 6은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"4 × 6은 얼마인가요?","explanation":["4 × 6은 4의 6배예요.","4씩 뛰어 세면 4, 8, 12, 16, 20, 24.","그래서 4 × 6 = 24예요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"options":[{"t":"24","correct":true},{"t":"10","mis":"M2-2-u2-X11"},{"t":"28","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#5','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C5',1,'mc','auto','7 × 4는 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 × 4는 얼마인가요?","explanation":["7 × 4는 7의 4배예요.","7씩 뛰어 세면 7, 14, 21, 28.","그래서 7 × 4 = 28이에요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"options":[{"t":"28","correct":true},{"t":"11","mis":"M2-2-u2-X11"},{"t":"35","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#6','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C6',1,'mc','auto','9 × 2는 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9 × 2는 얼마인가요?","explanation":["9 × 2는 9의 2배예요.","9씩 뛰어 세면 9, 18.","그래서 9 × 2 = 18이에요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"options":[{"t":"18","correct":true},{"t":"11","mis":"M2-2-u2-X11"},{"t":"27","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#7','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C7',1,'mc','auto','0 × 6은 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"0 × 6은 얼마인가요?","explanation":["0 × 6은 0을 6번 더한 것이에요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 0 × 6 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"options":[{"t":"0","correct":true},{"t":"6","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#8','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 3과 위쪽 7이 만나는 칸이에요.","그래서 3 × 7의 곱을 써요 — 3 × 6 = 18에 3을 더해도 돼요.","3 × 7 = 21이에요."],"variant_rule":{"gugu":{"ask":"cell"}},"options":[{"t":"21","correct":true},{"t":"24","mis":"M2-2-u2-X09"},{"t":"18","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[1,2,3,4],"cols":[3,4,5,6,7],"q":[3,7],"blank":[[4,7],[3,4]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#9','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 6단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 6단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["6단의 곱은 6, 12, 18, …예요.","곱하는 수가 1 커질 때마다 6씩 커져요.","그래서 6단 곱셈구구의 곱은 6씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"6","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"7","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[5,6,7],"cols":[1,2,3,4,5,6,7,8,9],"hrow":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#10','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',2,'mc','auto','4 × 6 = 24예요. 이것을 이용하면 4 × 7은 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"4 × 6 = 24예요. 이것을 이용하면 4 × 7은 얼마인가요?","explanation":["4 × 7은 4 × 6보다 4만큼 더 커요.","24 + 4 = 28이에요.","한 번 더 더할 때는 곱하는 수 7이 아니라 4를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"28","correct":true},{"t":"25","mis":"M2-2-u2-X01"},{"t":"31","mis":"M2-2-u2-X17"},{"t":"32","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#11','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 5는 7 × 4보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":11,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 5는 7 × 4보다 얼마 더 큰가요?","explanation":["7 × 4는 7을 4번, 7 × 5는 7을 5번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 28에서 35.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"5","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#12','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C6',2,'mc','auto','9 × □ = 36에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 36에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 36인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27, 36 — 4번이에요.","9 × 4 = 36이라 □는 4예요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"4","correct":true},{"t":"5","mis":"M2-2-u2-X02"},{"t":"3","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#13','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',2,'mc','auto','필통 한 개에 연필이 6자루씩 있어요. 필통 4개의 연필은 모두 몇 자루인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":13,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"필통 한 개에 연필이 6자루씩 있어요. 필통 4개의 연필은 모두 몇 자루인가요?","explanation":["필통 한 개에 6자루씩, 4개이면 6씩 4묶음이에요.","6 × 4 = 24예요.","연필은 모두 24자루예요."],"variant_rule":{"mul":{"ask":"story","pmax":81}},"options":[{"t":"24자루","correct":true},{"t":"10자루","mis":"M2-2-u2-X06"},{"t":"4자루","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#14','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C3',2,'ox','auto','6 × 4는 3 × 4를 두 번 더한 것과 같아요.',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":14,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 4는 3 × 4를 두 번 더한 것과 같아요.","answer":"O","reason_options":[{"t":"6씩 4묶음은 3씩 8묶음과 같아서 12 + 12 = 24니까","correct":true},{"t":"3단과 6단은 서로 관계가 없으니까","mis":"M2-2-u2-X10"}],"mis":"M2-2-u2-X10","explanation":["3 × 4 = 12예요.","12 + 12 = 24 = 6 × 4예요.","6단의 곱은 같은 수를 곱한 3단의 곱의 2배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#15','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 6인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":15,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 6인 것은 모두 몇 개인가요?","explanation":["곱이 6인 곱셈구구는 1 × 6, 2 × 3, 3 × 2, 6 × 1이에요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u2-X13"},{"t":"5","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#16','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C7',2,'ox','auto','5 × 0 = 5입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":16,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"5 × 0 = 5입니다.","explanation":["5 × 0은 5를 0번 더한 것 — 하나도 없어요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 5 × 0 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"answer":"X","reason_options":[{"t":"5 × 0은 5가 아니라 0이 되니까","correct":true},{"t":"0을 곱하면 그 수가 그대로 남으니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#17','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',3,'mc','auto','연결 모형이 왼쪽에 6개씩 2줄, 오른쪽에 3개씩 4줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X18']::text[],false,'{"seq":17,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"연결 모형이 왼쪽에 6개씩 2줄, 오른쪽에 3개씩 4줄 붙어 있어요. 연결 모형은 모두 몇 개인가요?","options":[{"t":"24개","correct":true},{"t":"15개","mis":"M2-2-u2-X17"},{"t":"12개","mis":"M2-2-u2-X18"}],"explanation":["왼쪽은 6 × 2 = 12개예요.","오른쪽은 3 × 4 = 12개예요.","12 + 12 = 24이니 모두 24개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#18','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#19','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C10',3,'mc','auto','2단 곱셈구구의 곱 2, 4, 6, 8, 10, 12, 14, 16, 18에서 일의 자리 숫자만 차례로 보면 어떤 규칙이 있나요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":19,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"2단 곱셈구구의 곱 2, 4, 6, 8, 10, 12, 14, 16, 18에서 일의 자리 숫자만 차례로 보면 어떤 규칙이 있나요?","options":[{"t":"2, 4, 6, 8, 0이 되풀이돼요","correct":true},{"t":"1씩 커져요","mis":"M2-2-u2-X16"},{"t":"2, 4, 6, 8, 10이 되풀이돼요","mis":"M2-2-u2-X16"}],"explanation":["일의 자리 숫자만 쓰면 2, 4, 6, 8, 0, 2, 4, 6, 8이에요.","2, 4, 6, 8, 0이 되풀이돼요.","10은 일의 자리 숫자가 아니라 곱 전체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#20','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 0점에 4번, 1점에 3번, 2점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":20,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 0점에 4번, 1점에 3번, 2점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"7점","correct":true},{"t":"11점","mis":"M2-2-u2-X08"},{"t":"9점","mis":"M2-2-u2-X05"}],"explanation":["0 × 4 = 0, 1 × 3 = 3, 2 × 2 = 4예요.","0 + 3 + 4 = 7이에요.","9는 맞힌 횟수를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#21','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C6',3,'mc','auto','9 × 2부터 9 × 9까지 9단 곱셈구구의 곱에서 십의 자리 숫자와 일의 자리 숫자를 더하면 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":21,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9 × 2부터 9 × 9까지 9단 곱셈구구의 곱에서 십의 자리 숫자와 일의 자리 숫자를 더하면 얼마인가요?","options":[{"t":"9","correct":true},{"t":"10","mis":"M2-2-u2-X16"},{"t":"곱하는 수와 같아요","mis":"M2-2-u2-X16"}],"explanation":["18은 1 + 8, 27은 2 + 7, 36은 3 + 6이에요.","모두 9예요.","9단의 곱은 두 숫자의 합이 9예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#22','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C4',3,'error','auto','4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X10','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C4","difficulty":3,"kind":"error","stem":"4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「4단과 8단은 서로 관계가 없어.」","correct":true,"mis_target":"M2-2-u2-X10"},{"t":"서아 — 「8 × 3은 4 × 3을 두 번 더한 것과 같아.」","mis":"M2-2-u2-X15"},{"t":"하루 — 「4 × 6과 8 × 3은 곱이 24로 같아.」","mis":"M2-2-u2-X15"}],"explanation":["8씩 한 묶음은 4씩 두 묶음이에요.","그래서 8단의 곱은 같은 수를 곱한 4단의 곱의 2배예요.","지우의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#23','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C10',4,'essay','teacher','2단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"2단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.","answer_guide":{"answer":"예: 2, 4, 6, 8, 10, 12, 14, 16, 18. 일의 자리 숫자는 2, 4, 6, 8, 0, 2, 4, 6, 8로 2, 4, 6, 8, 0이 되풀이된다.","scoring_points":["곱을 바르게 구했는가","일의 자리 숫자를 차례로 바르게 썼는가","되풀이되는 규칙이나 같은 무늬가 나오는 까닭을 썼는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","같은 숫자가 되풀이되는지 살펴요.","되풀이되는 숫자를 둥근 판에 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#24','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C9',4,'essay','teacher','의자가 한 줄에 5개씩 6줄로 놓여 있는데 두 자리가 비어 있어요. 의자의 수를 곱셈구구로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"의자가 한 줄에 5개씩 6줄로 놓여 있는데 두 자리가 비어 있어요. 의자의 수를 곱셈구구로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 빈자리까지 채우면 5 × 6 = 30개이다. 두 자리가 비었으므로 30 − 2 = 28개이다.","scoring_points":["곱셈구구로 나누어 곱하거나 빈자리를 채워 곱했는가","더하거나 빼는 과정을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["같은 수씩 놓인 덩이를 찾아 곱해요.","빈자리는 빼고, 덩이가 둘이면 두 곱을 더해요.","하나씩 세는 것보다 빠르고 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_a#25','math',2,2,'u2','','g2_2_math_u2_review_a','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 곱이 12인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 곱이 12인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 2 × 6, 3 × 4, 4 × 3, 6 × 2. 곱셈표에서 12가 있는 칸을 모두 찾고, 두 수를 바꾼 것도 함께 썼다.","scoring_points":["곱이 12인 곱셈구구를 하나 이상 찾았는가","두 수를 바꾼 것과 다른 단의 것까지 모두 찾았는가","곱셈표에서 12인 칸을 찾았다는 등 방법을 썼는가"]},"explanation":["곱셈표에서 같은 수가 있는 칸을 모두 찾아요.","두 수를 바꾸어 곱해도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#1','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","8에서 2만큼 더 뛰면 10이에요.","2씩 5번 뛰어 센 수 — 2씩 5묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["10"],"asset":{"type":"jump_row","cells":[2,4,6,8,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#2','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C2',1,'sa','auto','5 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 7은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 7은 5의 7배예요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30, 35.","그래서 5 × 7 = 35예요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["35"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#3','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C3',1,'sa','auto','6 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"6 × 4는 얼마인가요? 숫자로 쓰세요.","explanation":["6 × 4는 6의 4배예요.","6씩 뛰어 세면 6, 12, 18, 24.","그래서 6 × 4 = 24예요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["24"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#4','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',1,'mc','auto','8 × 3은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"8 × 3은 얼마인가요?","explanation":["8 × 3은 8의 3배예요.","8씩 뛰어 세면 8, 16, 24.","그래서 8 × 3 = 24예요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"options":[{"t":"24","correct":true},{"t":"11","mis":"M2-2-u2-X11"},{"t":"32","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#5','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C5',1,'mc','auto','7 × 6은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 × 6은 얼마인가요?","explanation":["7 × 6은 7의 6배예요.","7씩 뛰어 세면 7, 14, 21, 28, 35, 42.","그래서 7 × 6 = 42예요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"options":[{"t":"42","correct":true},{"t":"13","mis":"M2-2-u2-X11"},{"t":"49","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#6','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C6',1,'mc','auto','9 × 5는 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9 × 5는 얼마인가요?","explanation":["9 × 5는 9의 5배예요.","9씩 뛰어 세면 9, 18, 27, 36, 45.","그래서 9 × 5 = 45예요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"options":[{"t":"45","correct":true},{"t":"14","mis":"M2-2-u2-X11"},{"t":"54","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#7','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C7',1,'mc','auto','3 × 0은 얼마인가요?',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"3 × 0은 얼마인가요?","explanation":["3 × 0은 3을 0번 더한 것 — 하나도 없어요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 3 × 0 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"options":[{"t":"0","correct":true},{"t":"3","mis":"M2-2-u2-X08"},{"t":"1","mis":"M2-2-u2-X08"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#8','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 6과 위쪽 4가 만나는 칸이에요.","그래서 6 × 4의 곱을 써요 — 6 × 3 = 18에 6을 더해도 돼요.","6 × 4 = 24예요."],"variant_rule":{"gugu":{"ask":"cell"}},"options":[{"t":"24","correct":true},{"t":"30","mis":"M2-2-u2-X09"},{"t":"18","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[4,5,6,7],"cols":[1,2,3,4,5],"q":[6,4],"blank":[[7,4],[6,2]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#9','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 8단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 8단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["8단의 곱은 8, 16, 24, …예요.","곱하는 수가 1 커질 때마다 8씩 커져요.","그래서 8단 곱셈구구의 곱은 8씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"8","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"9","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[7,8,9],"cols":[1,2,3,4,5,6,7,8,9],"hrow":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#10','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',2,'mc','auto','8 × 4 = 32예요. 이것을 이용하면 8 × 5는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 4 = 32예요. 이것을 이용하면 8 × 5는 얼마인가요?","explanation":["8 × 5는 8 × 4보다 8만큼 더 커요.","32 + 8 = 40이에요.","한 번 더 더할 때는 곱하는 수 5가 아니라 8을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"40","correct":true},{"t":"33","mis":"M2-2-u2-X01"},{"t":"37","mis":"M2-2-u2-X17"},{"t":"48","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#11','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 8은 7 × 7보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":11,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 8은 7 × 7보다 얼마 더 큰가요?","explanation":["7 × 7은 7을 7번, 7 × 8은 7을 8번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 49에서 56.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"8","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#12','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C6',2,'mc','auto','9 × □ = 63에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 63에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 63인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27, 36, 45, 54, 63 — 7번이에요.","9 × 7 = 63이라 □는 7이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"7","correct":true},{"t":"8","mis":"M2-2-u2-X02"},{"t":"6","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#13','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',2,'mc','auto','쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 6개의 딸기는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":13,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"쟁반 한 개에 딸기가 5개씩 있어요. 쟁반 6개의 딸기는 모두 몇 개인가요?","explanation":["쟁반 한 개에 5개씩, 6개이면 5씩 6묶음이에요.","5 × 6 = 30이에요.","딸기는 모두 30개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81}},"options":[{"t":"30개","correct":true},{"t":"11개","mis":"M2-2-u2-X06"},{"t":"6개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#14','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C3',2,'ox','auto','3 × 7은 7 × 3보다 커요.',ARRAY['M2-2-u2-X13']::text[],false,'{"seq":14,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"3 × 7은 7 × 3보다 커요.","answer":"X","reason_options":[{"t":"두 수를 바꾸어 곱해도 곱은 21로 같으니까","correct":true},{"t":"곱하는 수가 크면 곱도 크니까","mis":"M2-2-u2-X13"}],"mis":"M2-2-u2-X13","explanation":["3 × 7 = 21이에요.","7 × 3 = 21이에요.","그래서 두 곱은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#15','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 18인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":15,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 18인 것은 모두 몇 개인가요?","explanation":["곱이 18인 곱셈구구는 2 × 9, 3 × 6, 6 × 3, 9 × 2예요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u2-X13"},{"t":"5","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#16','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C7',2,'ox','auto','1 × 7 = 7입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":16,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"1 × 7 = 7입니다.","explanation":["1 × 7은 1을 7번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 1 × 7 = 7이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"answer":"O","reason_options":[{"t":"1을 7번 더하면 7이 되니까","correct":true},{"t":"1을 곱하면 1이 되니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#17','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',3,'mc','auto','책상이 한 줄에 6개씩 4줄로 놓여 있는데, 두 자리가 비어 있어요. 책상은 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":17,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"책상이 한 줄에 6개씩 4줄로 놓여 있는데, 두 자리가 비어 있어요. 책상은 모두 몇 개인가요?","options":[{"t":"22개","correct":true},{"t":"24개","mis":"M2-2-u2-X18"},{"t":"10개","mis":"M2-2-u2-X06"}],"explanation":["빈자리까지 채우면 6 × 4 = 24개예요.","두 자리가 비었어요.","24 − 2 = 22이니 22개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#18','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#19','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C10',3,'mc','auto','5단 곱셈구구의 곱의 일의 자리 숫자를 0부터 9까지 둥글게 적힌 판에 차례로 이으면 어떤 모양이 나올까요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":19,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"5단 곱셈구구의 곱의 일의 자리 숫자를 0부터 9까지 둥글게 적힌 판에 차례로 이으면 어떤 모양이 나올까요?","options":[{"t":"5와 0을 오가는 한 줄","correct":true},{"t":"별 모양","mis":"M2-2-u2-X16"},{"t":"오각형","mis":"M2-2-u2-X16"}],"explanation":["5단의 곱은 5, 10, 15, 20, …이에요.","일의 자리 숫자는 5와 0뿐이에요.","그래서 5와 0을 오가는 한 줄이 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#20','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 0점에 3번, 1점에 5번, 3점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":20,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 0점에 3번, 1점에 5번, 3점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"11점","correct":true},{"t":"14점","mis":"M2-2-u2-X08"},{"t":"10점","mis":"M2-2-u2-X05"}],"explanation":["0 × 3 = 0, 1 × 5 = 5, 3 × 2 = 6이에요.","0 + 5 + 6 = 11이에요.","10은 맞힌 횟수를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#21','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C6',3,'mc','auto','9 × 7의 곱에서 십의 자리 숫자는 얼마인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":21,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9 × 7의 곱에서 십의 자리 숫자는 얼마인가요?","options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u2-X16"},{"t":"3","mis":"M2-2-u2-X16"}],"explanation":["9 × 7 = 63이에요.","십의 자리 숫자는 6이에요.","9단에서 곱의 십의 자리 숫자는 곱하는 수보다 1 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#22','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C4',3,'error','auto','4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X10','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C4","difficulty":3,"kind":"error","stem":"4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「4 × 5가 20이니까 8 × 5는 28이야.」","correct":true,"mis_target":"M2-2-u2-X10"},{"t":"은솔 — 「8 × 5는 4 × 5의 2배라서 40이야.」","mis":"M2-2-u2-X15"},{"t":"예린 — 「우유 4갑씩 6줄은 8갑씩 3줄과 같아.」","mis":"M2-2-u2-X15"}],"explanation":["8 × 5는 4 × 5의 2배예요.","20의 2배는 40이에요.","도윤이는 2배 하지 않고 8만 더했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#23','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C10',4,'essay','teacher','5단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"5단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.","answer_guide":{"answer":"예: 5, 10, 15, 20, 25, 30, 35, 40, 45. 일의 자리 숫자는 5, 0, 5, 0, …으로 5와 0이 번갈아 되풀이된다.","scoring_points":["곱을 바르게 구했는가","일의 자리 숫자를 차례로 바르게 썼는가","되풀이되는 규칙이나 같은 무늬가 나오는 까닭을 썼는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","같은 숫자가 되풀이되는지 살펴요.","되풀이되는 숫자를 둥근 판에 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#24','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C9',4,'essay','teacher','연결 모형이 4개씩 3줄과 2개씩 5줄로 붙어 있어요. 연결 모형의 수를 곱셈구구로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"연결 모형이 4개씩 3줄과 2개씩 5줄로 붙어 있어요. 연결 모형의 수를 곱셈구구로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 4 × 3 = 12, 2 × 5 = 10이다. 두 덩이를 더하면 12 + 10 = 22개이다.","scoring_points":["곱셈구구로 나누어 곱하거나 빈자리를 채워 곱했는가","더하거나 빼는 과정을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["같은 수씩 놓인 덩이를 찾아 곱해요.","빈자리는 빼고, 덩이가 둘이면 두 곱을 더해요.","하나씩 세는 것보다 빠르고 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_b#25','math',2,2,'u2','','g2_2_math_u2_review_b','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 곱이 18인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 곱이 18인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 2 × 9, 3 × 6, 6 × 3, 9 × 2. 곱셈표에서 18이 있는 칸을 모두 찾고, 두 수를 바꾼 것도 함께 썼다.","scoring_points":["곱이 18인 곱셈구구를 하나 이상 찾았는가","두 수를 바꾼 것과 다른 단의 것까지 모두 찾았는가","곱셈표에서 18인 칸을 찾았다는 등 방법을 썼는가"]},"explanation":["곱셈표에서 같은 수가 있는 칸을 모두 찾아요.","두 수를 바꾸어 곱해도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#1','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","10에서 2만큼 더 뛰면 12예요.","2씩 6번 뛰어 센 수 — 2씩 6묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["12"],"asset":{"type":"jump_row","cells":[2,4,6,8,10,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#2','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C2',1,'sa','auto','5 × 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 8은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 8은 5의 8배예요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30, 35, 40.","그래서 5 × 8 = 40이에요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["40"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#3','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C3',1,'sa','auto','3 × 9는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"3 × 9는 얼마인가요? 숫자로 쓰세요.","explanation":["3 × 9는 3의 9배예요.","3씩 뛰어 세면 3, 6, 9, 12, 15, 18, 21, 24, 27.","그래서 3 × 9 = 27이에요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["27"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#4','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C4',1,'mc','auto','4 × 8은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"4 × 8은 얼마인가요?","explanation":["4 × 8은 4의 8배예요.","4씩 뛰어 세면 4, 8, 12, 16, 20, 24, 28, 32.","그래서 4 × 8 = 32예요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"options":[{"t":"32","correct":true},{"t":"12","mis":"M2-2-u2-X11"},{"t":"36","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#5','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C5',1,'mc','auto','7 × 8은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 × 8은 얼마인가요?","explanation":["7 × 8은 7의 8배예요.","7씩 뛰어 세면 7, 14, 21, 28, 35, 42, 49, 56.","그래서 7 × 8 = 56이에요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"options":[{"t":"56","correct":true},{"t":"15","mis":"M2-2-u2-X11"},{"t":"63","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#6','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C6',1,'mc','auto','9 × 7은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9 × 7은 얼마인가요?","explanation":["9 × 7은 9의 7배예요.","9씩 뛰어 세면 9, 18, 27, 36, 45, 54, 63.","그래서 9 × 7 = 63이에요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"options":[{"t":"63","correct":true},{"t":"16","mis":"M2-2-u2-X11"},{"t":"72","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#7','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C7',1,'mc','auto','1 × 8은 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"1 × 8은 얼마인가요?","explanation":["1 × 8은 1을 8번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 1 × 8 = 8이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"options":[{"t":"8","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"9","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#8','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 4와 위쪽 8이 만나는 칸이에요.","그래서 4 × 8의 곱을 써요 — 4 × 7 = 28에 4를 더해도 돼요.","4 × 8 = 32예요."],"variant_rule":{"gugu":{"ask":"cell"}},"options":[{"t":"32","correct":true},{"t":"36","mis":"M2-2-u2-X09"},{"t":"28","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[2,3,4,5],"cols":[4,5,6,7,8],"q":[4,8],"blank":[[5,8],[4,5]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#9','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 3단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 3단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["3단의 곱은 3, 6, 9, …예요.","곱하는 수가 1 커질 때마다 3씩 커져요.","그래서 3단 곱셈구구의 곱은 3씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"3","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"4","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[2,3,4],"cols":[1,2,3,4,5,6,7,8,9],"hrow":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#10','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C4',2,'mc','auto','4 × 8 = 32예요. 이것을 이용하면 4 × 9는 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"4 × 8 = 32예요. 이것을 이용하면 4 × 9는 얼마인가요?","explanation":["4 × 9는 4 × 8보다 4만큼 더 커요.","32 + 4 = 36이에요.","한 번 더 더할 때는 곱하는 수 9가 아니라 4를 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"36","correct":true},{"t":"33","mis":"M2-2-u2-X01"},{"t":"41","mis":"M2-2-u2-X17"},{"t":"40","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#11','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 3은 7 × 2보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":11,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 3은 7 × 2보다 얼마 더 큰가요?","explanation":["7 × 2는 7을 2번, 7 × 3은 7을 3번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 14에서 21.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"3","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#12','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C6',2,'mc','auto','9 × □ = 27에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 27에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 27인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27 — 3번이에요.","9 × 3 = 27이라 □는 3이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"3","correct":true},{"t":"4","mis":"M2-2-u2-X02"},{"t":"2","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#13','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',2,'mc','auto','주머니 한 개에 구슬이 7개씩 있어요. 주머니 3개의 구슬은 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":13,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"주머니 한 개에 구슬이 7개씩 있어요. 주머니 3개의 구슬은 모두 몇 개인가요?","explanation":["주머니 한 개에 7개씩, 3개이면 7씩 3묶음이에요.","7 × 3 = 21이에요.","구슬은 모두 21개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81}},"options":[{"t":"21개","correct":true},{"t":"10개","mis":"M2-2-u2-X06"},{"t":"3개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#14','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C3',2,'ox','auto','6 × 6은 6 × 5에 6을 더한 것이에요.',ARRAY['M2-2-u2-X17']::text[],false,'{"seq":14,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"6 × 6은 6 × 5에 6을 더한 것이에요.","answer":"O","reason_options":[{"t":"6을 한 번 더 더하면 되니까 30 + 6 = 36","correct":true},{"t":"6 × 5에 5를 더해야 하니까","mis":"M2-2-u2-X17"}],"mis":"M2-2-u2-X17","explanation":["6 × 5 = 30이에요.","6 × 6은 6 × 5보다 6만큼 커요.","30 + 6 = 36이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#15','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 16인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":15,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 16인 것은 모두 몇 개인가요?","explanation":["곱이 16인 곱셈구구는 2 × 8, 4 × 4, 8 × 2예요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 3개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"3","correct":true},{"t":"2","mis":"M2-2-u2-X13"},{"t":"4","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#16','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C7',2,'ox','auto','0 × 9 = 0입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":16,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"0 × 9 = 0입니다.","explanation":["0 × 9는 0을 9번 더한 것이에요.","0과 어떤 수의 곱, 어떤 수와 0의 곱은 늘 0이에요.","그래서 0 × 9 = 0이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"answer":"O","reason_options":[{"t":"0을 9번 더해도 0이니까","correct":true},{"t":"0을 곱하면 그 수가 그대로 남으니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#17','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',3,'mc','auto','의자가 한 줄에 7개씩 3줄 있고, 따로 4개가 더 있어요. 의자는 모두 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":17,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"의자가 한 줄에 7개씩 3줄 있고, 따로 4개가 더 있어요. 의자는 모두 몇 개인가요?","options":[{"t":"25개","correct":true},{"t":"21개","mis":"M2-2-u2-X18"},{"t":"14개","mis":"M2-2-u2-X06"}],"explanation":["줄에 놓인 의자는 7 × 3 = 21개예요.","따로 있는 4개를 더해요.","21 + 4 = 25이니 모두 25개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#18','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#19','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C10',3,'mc','auto','8단 곱셈구구의 곱 8, 16, 24, 32, 40의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":19,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"8단 곱셈구구의 곱 8, 16, 24, 32, 40의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"8, 6, 4, 2, 0","correct":true},{"t":"8, 16, 24, 32, 40","mis":"M2-2-u2-X16"},{"t":"8, 7, 6, 5, 4","mis":"M2-2-u2-X16"}],"explanation":["일의 자리 숫자만 써요.","8, 6, 4, 2, 0이에요.","2단(2, 4, 6, 8, 0)과 같은 숫자를 거꾸로 이어 같은 무늬가 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#20','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 0점에 5번, 1점에 1번, 4점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":20,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 0점에 5번, 1점에 1번, 4점에 2번 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"9점","correct":true},{"t":"14점","mis":"M2-2-u2-X08"},{"t":"8점","mis":"M2-2-u2-X05"}],"explanation":["0 × 5 = 0, 1 × 1 = 1, 4 × 2 = 8이에요.","0 + 1 + 8 = 9예요.","8은 맞힌 횟수를 더한 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#21','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C6',3,'mc','auto','9단 곱셈구구에서 곱하는 수가 1 커지면 곱의 일의 자리 숫자는 어떻게 되나요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":21,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9단 곱셈구구에서 곱하는 수가 1 커지면 곱의 일의 자리 숫자는 어떻게 되나요?","options":[{"t":"1씩 작아져요","correct":true},{"t":"1씩 커져요","mis":"M2-2-u2-X16"},{"t":"9씩 작아져요","mis":"M2-2-u2-X16"}],"explanation":["9, 18, 27, 36, …에서 일의 자리 숫자는 9, 8, 7, 6, …이에요.","1씩 작아져요.","십의 자리 숫자는 1씩 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#22','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C4',3,'error','auto','4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X17','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C4","difficulty":3,"kind":"error","stem":"4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「8 × 6은 8 × 3에 3을 더한 27이야.」","correct":true,"mis_target":"M2-2-u2-X17"},{"t":"아린 — 「8 × 6은 8 × 3을 두 번 더한 48이야.」","mis":"M2-2-u2-X15"},{"t":"지안 — 「8 × 6은 8 × 5에 8을 더한 48이야.」","mis":"M2-2-u2-X15"}],"explanation":["8 × 6은 8 × 3을 두 번 더한 것이에요.","24 + 24 = 48이에요.","태민이는 8 × 3에 곱 대신 3을 더했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#23','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C10',4,'essay','teacher','4단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"4단 곱셈구구의 곱을 쓰고, 곱의 일의 자리 숫자를 차례로 써서 어떤 규칙이 있는지 설명해 보세요.","answer_guide":{"answer":"예: 4, 8, 12, 16, 20, 24, 28, 32, 36. 일의 자리 숫자는 4, 8, 2, 6, 0, 4, 8, 2, 6으로 4, 8, 2, 6, 0이 되풀이된다.","scoring_points":["곱을 바르게 구했는가","일의 자리 숫자를 차례로 바르게 썼는가","되풀이되는 규칙이나 같은 무늬가 나오는 까닭을 썼는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","같은 숫자가 되풀이되는지 살펴요.","되풀이되는 숫자를 둥근 판에 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#24','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C9',4,'essay','teacher','닭 4마리와 강아지 5마리가 있어요. 다리의 수를 곱셈구구로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"닭 4마리와 강아지 5마리가 있어요. 다리의 수를 곱셈구구로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 닭의 다리는 2 × 4 = 8개, 강아지의 다리는 4 × 5 = 20개이다. 8 + 20 = 28개이다.","scoring_points":["곱셈구구로 나누어 곱하거나 빈자리를 채워 곱했는가","더하거나 빼는 과정을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["같은 수씩 놓인 덩이를 찾아 곱해요.","빈자리는 빼고, 덩이가 둘이면 두 곱을 더해요.","하나씩 세는 것보다 빠르고 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_c#25','math',2,2,'u2','','g2_2_math_u2_review_c','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 곱이 16인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 곱이 16인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 2 × 8, 4 × 4, 8 × 2. 곱셈표에서 16이 있는 칸을 모두 찾았다. 4 × 4는 두 수가 같아 하나뿐이다.","scoring_points":["곱이 16인 곱셈구구를 하나 이상 찾았는가","두 수를 바꾼 것과 다른 단의 것까지 모두 찾았는가","곱셈표에서 16인 칸을 찾았다는 등 방법을 썼는가"]},"explanation":["곱셈표에서 같은 수가 있는 칸을 모두 찾아요.","두 수를 바꾸어 곱해도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#1','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-2-u2-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","4에서 2만큼 더 뛰면 6이에요.","2씩 3번 뛰어 센 수 — 2씩 3묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip","ks":[2],"pmax":45}},"answer":["6"],"asset":{"type":"jump_row","cells":[2,4,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#2','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C2',1,'sa','auto','5 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-2-u2-C2","difficulty":1,"kind":"sa","stem":"5 × 4는 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 4는 5의 4배예요.","5씩 뛰어 세면 5, 10, 15, 20.","그래서 5 × 4 = 20이에요."],"variant_rule":{"mul":{"ask":"value","ks":[5],"pmax":81}},"answer":["20"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#3','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C3',1,'sa','auto','6 × 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-2-u2-C3","difficulty":1,"kind":"sa","stem":"6 × 8은 얼마인가요? 숫자로 쓰세요.","explanation":["6 × 8은 6의 8배예요.","6씩 뛰어 세면 6, 12, 18, 24, 30, 36, 42, 48.","그래서 6 × 8 = 48이에요."],"variant_rule":{"mul":{"ask":"value","ks":[3,6],"pmax":81}},"answer":["48"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#4','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',1,'mc','auto','8 × 7은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":4,"concept":"M2-2-u2-C4","difficulty":1,"kind":"mc","stem":"8 × 7은 얼마인가요?","explanation":["8 × 7은 8의 7배예요.","8씩 뛰어 세면 8, 16, 24, 32, 40, 48, 56.","그래서 8 × 7 = 56이에요."],"variant_rule":{"mul":{"ask":"value","ks":[4,8],"pmax":81}},"options":[{"t":"56","correct":true},{"t":"15","mis":"M2-2-u2-X11"},{"t":"64","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#5','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C5',1,'mc','auto','7 × 3은 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":5,"concept":"M2-2-u2-C5","difficulty":1,"kind":"mc","stem":"7 × 3은 얼마인가요?","explanation":["7 × 3은 7의 3배예요.","7씩 뛰어 세면 7, 14, 21.","그래서 7 × 3 = 21이에요."],"variant_rule":{"mul":{"ask":"value","ks":[7],"pmax":81}},"options":[{"t":"21","correct":true},{"t":"10","mis":"M2-2-u2-X11"},{"t":"28","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#6','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',1,'mc','auto','9 × 4는 얼마인가요?',ARRAY['M2-2-u2-X11','M2-2-u2-X02']::text[],true,'{"seq":6,"concept":"M2-2-u2-C6","difficulty":1,"kind":"mc","stem":"9 × 4는 얼마인가요?","explanation":["9 × 4는 9의 4배예요.","9씩 뛰어 세면 9, 18, 27, 36.","그래서 9 × 4 = 36이에요."],"variant_rule":{"mul":{"ask":"value","ks":[9],"pmax":81}},"options":[{"t":"36","correct":true},{"t":"13","mis":"M2-2-u2-X11"},{"t":"45","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#7','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C7',1,'mc','auto','7 × 1은 얼마인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X06']::text[],true,'{"seq":7,"concept":"M2-2-u2-C7","difficulty":1,"kind":"mc","stem":"7 × 1은 얼마인가요?","explanation":["7 × 1은 7을 한 번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 7 × 1 = 7이에요."],"variant_rule":{"gugu":{"ask":"zero"}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X08"},{"t":"8","mis":"M2-2-u2-X06"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#8','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',1,'mc','auto','곱셈표의 ?에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X09']::text[],true,'{"seq":8,"concept":"M2-2-u2-C8","difficulty":1,"kind":"mc","stem":"곱셈표의 ?에 알맞은 수는 얼마인가요?","explanation":["?는 왼쪽 7과 위쪽 5가 만나는 칸이에요.","그래서 7 × 5의 곱을 써요 — 7 × 4 = 28에 7을 더해도 돼요.","7 × 5 = 35예요."],"variant_rule":{"gugu":{"ask":"cell"}},"options":[{"t":"35","correct":true},{"t":"42","mis":"M2-2-u2-X09"},{"t":"28","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[5,6,7,8],"cols":[1,2,3,4,5],"q":[7,5],"blank":[[8,5],[7,2]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#9','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',2,'mc','auto','곱셈표에서 색칠한 9단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?',ARRAY['M2-2-u2-X01','M2-2-u2-X09']::text[],true,'{"seq":9,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"곱셈표에서 색칠한 9단 곱셈구구의 곱은 오른쪽으로 한 칸 갈 때마다 얼마씩 커지나요?","explanation":["9단의 곱은 9, 18, 27, …예요.","곱하는 수가 1 커질 때마다 9씩 커져요.","그래서 9단 곱셈구구의 곱은 9씩 커져요 — 1씩이 아니에요."],"variant_rule":{"gugu":{"ask":"step"}},"options":[{"t":"9","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"10","mis":"M2-2-u2-X09"}],"asset":{"type":"gugu_table","rows":[7,8,9],"cols":[1,2,3,4,5,6,7,8,9],"hrow":9}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#10','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',2,'mc','auto','8 × 5 = 40이에요. 이것을 이용하면 8 × 6은 얼마인가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17','M2-2-u2-X02']::text[],true,'{"seq":10,"concept":"M2-2-u2-C4","difficulty":2,"kind":"mc","stem":"8 × 5 = 40이에요. 이것을 이용하면 8 × 6은 얼마인가요?","explanation":["8 × 6은 8 × 5보다 8만큼 더 커요.","40 + 8 = 48이에요.","한 번 더 더할 때는 곱하는 수 6이 아니라 8을 더해요."],"variant_rule":{"gugu":{"ask":"build","ks":[4,8]}},"options":[{"t":"48","correct":true},{"t":"41","mis":"M2-2-u2-X01"},{"t":"46","mis":"M2-2-u2-X17"},{"t":"56","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#11','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C5',2,'mc','auto','7 × 9는 7 × 8보다 얼마 더 큰가요?',ARRAY['M2-2-u2-X01','M2-2-u2-X17']::text[],true,'{"seq":11,"concept":"M2-2-u2-C5","difficulty":2,"kind":"mc","stem":"7 × 9는 7 × 8보다 얼마 더 큰가요?","explanation":["7 × 8은 7을 8번, 7 × 9는 7을 9번 더한 것이에요.","7을 한 번 더 더했으니 7만큼 더 커요 — 56에서 63.","곱하는 수가 1 커지면 곱은 7만큼 커져요."],"variant_rule":{"gugu":{"ask":"next","ks":[7]}},"options":[{"t":"7","correct":true},{"t":"1","mis":"M2-2-u2-X01"},{"t":"9","mis":"M2-2-u2-X17"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#12','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',2,'mc','auto','9 × □ = 54에서 □ 안에 알맞은 수는 얼마인가요?',ARRAY['M2-2-u2-X02']::text[],true,'{"seq":12,"concept":"M2-2-u2-C6","difficulty":2,"kind":"mc","stem":"9 × □ = 54에서 □ 안에 알맞은 수는 얼마인가요?","explanation":["9단 곱셈구구에서 곱이 54인 것을 찾아요.","9씩 뛰어 세면 9, 18, 27, 36, 45, 54 — 6번이에요.","9 × 6 = 54라 □는 6이에요."],"variant_rule":{"gugu":{"ask":"miss","ks":[9]}},"options":[{"t":"6","correct":true},{"t":"7","mis":"M2-2-u2-X02"},{"t":"5","mis":"M2-2-u2-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#13','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',2,'mc','auto','거미 한 마리에 다리가 8개씩 있어요. 거미 5마리의 다리는 모두 몇 개인가요?',ARRAY['M2-2-u2-X06','M2-2-u2-X14']::text[],true,'{"seq":13,"concept":"M2-2-u2-C9","difficulty":2,"kind":"mc","stem":"거미 한 마리에 다리가 8개씩 있어요. 거미 5마리의 다리는 모두 몇 개인가요?","explanation":["거미 한 마리에 8개씩, 5마리이면 8씩 5묶음이에요.","8 × 5 = 40이에요.","다리는 모두 40개예요."],"variant_rule":{"mul":{"ask":"story","pmax":81}},"options":[{"t":"40개","correct":true},{"t":"13개","mis":"M2-2-u2-X06"},{"t":"5개","mis":"M2-2-u2-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#14','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C3',2,'ox','auto','3 × 1부터 3 × 9까지의 곱 가운데 6단의 곱도 되는 수는 6, 12, 18, 24예요.',ARRAY['M2-2-u2-X10']::text[],false,'{"seq":14,"concept":"M2-2-u2-C3","difficulty":2,"kind":"ox","stem":"3 × 1부터 3 × 9까지의 곱 가운데 6단의 곱도 되는 수는 6, 12, 18, 24예요.","answer":"O","reason_options":[{"t":"6단의 곱은 6씩 커지고, 3단의 곱 가운데 6씩 커지는 수가 6, 12, 18, 24니까","correct":true},{"t":"3단의 곱과 6단의 곱은 겹치는 수가 없으니까","mis":"M2-2-u2-X10"}],"mis":"M2-2-u2-X10","explanation":["3단의 곱: 3, 6, 9, 12, 15, 18, 21, 24, 27","6단의 곱: 6, 12, 18, 24, 30, …","겹치는 수는 6, 12, 18, 24예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#15','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',2,'mc','auto','1단부터 9단까지의 곱셈구구 가운데 곱이 8인 것은 모두 몇 개인가요?',ARRAY['M2-2-u2-X13','M2-2-u2-X09']::text[],true,'{"seq":15,"concept":"M2-2-u2-C8","difficulty":2,"kind":"mc","stem":"1단부터 9단까지의 곱셈구구 가운데 곱이 8인 것은 모두 몇 개인가요?","explanation":["곱이 8인 곱셈구구는 1 × 8, 2 × 4, 4 × 2, 8 × 1이에요.","두 수를 바꾸어 곱한 것도 따로 세어요.","그래서 모두 4개예요."],"variant_rule":{"gugu":{"ask":"tfind"}},"options":[{"t":"4","correct":true},{"t":"3","mis":"M2-2-u2-X13"},{"t":"5","mis":"M2-2-u2-X09"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#16','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C7',2,'ox','auto','4 × 1 = 1입니다.',ARRAY['M2-2-u2-X08']::text[],true,'{"seq":16,"concept":"M2-2-u2-C7","difficulty":2,"kind":"ox","stem":"4 × 1 = 1입니다.","explanation":["4 × 1은 4를 한 번 더한 것이에요.","1과 어떤 수의 곱, 어떤 수와 1의 곱은 늘 그 수예요.","그래서 4 × 1 = 4예요."],"variant_rule":{"gugu":{"ask":"zero"}},"answer":"X","reason_options":[{"t":"4 × 1은 1이 아니라 4가 되니까","correct":true},{"t":"1을 곱하면 1이 되니까","mis":"M2-2-u2-X08"}],"mis":"M2-2-u2-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#17','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',3,'mc','auto','쿠키가 한 접시에 8개씩 4접시 있었는데, 3개를 먹었어요. 남은 쿠키는 몇 개인가요?',ARRAY['M2-2-u2-X18','M2-2-u2-X06']::text[],false,'{"seq":17,"concept":"M2-2-u2-C9","difficulty":3,"kind":"mc","stem":"쿠키가 한 접시에 8개씩 4접시 있었는데, 3개를 먹었어요. 남은 쿠키는 몇 개인가요?","options":[{"t":"29개","correct":true},{"t":"32개","mis":"M2-2-u2-X18"},{"t":"35개","mis":"M2-2-u2-X06"}],"explanation":["처음 쿠키는 8 × 4 = 32개예요.","그중 3개를 먹었어요.","32 − 3 = 29이니 29개가 남았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#18','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',3,'mc','auto','두 곱의 크기를 견주어 ○ 안에 알맞은 것을 고르세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#19','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C10',3,'mc','auto','4단 곱셈구구의 곱 4, 8, 12, 16, 20의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?',ARRAY['M2-2-u2-X16']::text[],false,'{"seq":19,"concept":"M2-2-u2-C10","difficulty":3,"kind":"mc","stem":"4단 곱셈구구의 곱 4, 8, 12, 16, 20의 일의 자리 숫자를 차례로 쓴 것은 어느 것인가요?","options":[{"t":"4, 8, 2, 6, 0","correct":true},{"t":"4, 8, 1, 1, 2","mis":"M2-2-u2-X16"},{"t":"4, 5, 6, 7, 8","mis":"M2-2-u2-X16"}],"explanation":["일의 자리 숫자만 써요.","4, 8, 2, 6, 0이에요.","십의 자리 숫자(1, 1, 2)를 쓰면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#20','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C7',3,'mc','auto','과녁 맞히기에서 1점에 6번, 0점에 2번 맞혔고 5점에는 한 번도 못 맞혔어요. 얻은 점수는 모두 몇 점인가요?',ARRAY['M2-2-u2-X08','M2-2-u2-X05']::text[],false,'{"seq":20,"concept":"M2-2-u2-C7","difficulty":3,"kind":"mc","stem":"과녁 맞히기에서 1점에 6번, 0점에 2번 맞혔고 5점에는 한 번도 못 맞혔어요. 얻은 점수는 모두 몇 점인가요?","options":[{"t":"6점","correct":true},{"t":"11점","mis":"M2-2-u2-X08"},{"t":"8점","mis":"M2-2-u2-X05"}],"explanation":["1 × 6 = 6, 0 × 2 = 0, 5 × 0 = 0이에요.","6 + 0 + 0 = 6이에요.","한 번도 못 맞힌 5점은 0점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#21','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C6',3,'mc','auto','9 × 4 = 36이에요. 9 × 6의 곱을 바르게 말한 것은 어느 것인가요?',ARRAY['M2-2-u2-X16','M2-2-u2-X02']::text[],false,'{"seq":21,"concept":"M2-2-u2-C6","difficulty":3,"kind":"mc","stem":"9 × 4 = 36이에요. 9 × 6의 곱을 바르게 말한 것은 어느 것인가요?","options":[{"t":"54 — 십의 자리 5, 일의 자리 4","correct":true},{"t":"63 — 십의 자리 6, 일의 자리 3","mis":"M2-2-u2-X16"},{"t":"45 — 십의 자리 4, 일의 자리 5","mis":"M2-2-u2-X02"}],"explanation":["9 × 6은 9 × 4보다 9씩 두 번 커요 — 36 + 18 = 54예요.","십의 자리 5는 곱하는 수 6보다 1 작아요.","5 + 4 = 9로 9단의 규칙에도 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#22','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C4',3,'error','auto','4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-2-u2-X10','M2-2-u2-X15']::text[],false,'{"seq":22,"concept":"M2-2-u2-C4","difficulty":3,"kind":"error","stem":"4단과 8단에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「4 × 2와 8 × 2는 곱이 같아.」","correct":true,"mis_target":"M2-2-u2-X10"},{"t":"펭이 — 「4 × 8과 8 × 4는 곱이 같아.」","mis":"M2-2-u2-X15"},{"t":"다예 — 「4 × 4를 두 번 더하면 8 × 4야.」","mis":"M2-2-u2-X15"}],"explanation":["4 × 2 = 8, 8 × 2 = 16이에요.","8 × 2는 4 × 2의 2배예요.","곰이의 말이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#23','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C10',4,'essay','teacher','2단과 8단 곱셈구구의 곱의 일의 자리 숫자를 각각 다섯 개씩 차례로 쓰고, 둥근 판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-2-u2-C10","difficulty":4,"kind":"essay","stem":"2단과 8단 곱셈구구의 곱의 일의 자리 숫자를 각각 다섯 개씩 차례로 쓰고, 둥근 판에 이으면 같은 무늬가 나오는 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 2단은 2, 4, 6, 8, 0이고 8단은 8, 6, 4, 2, 0이다. 같은 숫자들을 순서만 거꾸로 이으므로 같은 무늬가 나온다.","scoring_points":["곱을 바르게 구했는가","일의 자리 숫자를 차례로 바르게 썼는가","되풀이되는 규칙이나 같은 무늬가 나오는 까닭을 썼는가"]},"explanation":["곱의 일의 자리 숫자만 따로 써요.","같은 숫자가 되풀이되는지 살펴요.","되풀이되는 숫자를 둥근 판에 이으면 무늬가 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#24','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C9',4,'essay','teacher','사물함이 한 줄에 6칸씩 4줄 있는데 3칸이 비어 있어요. 물건이 든 사물함의 수를 곱셈구구로 구하고 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-2-u2-C9","difficulty":4,"kind":"essay","stem":"사물함이 한 줄에 6칸씩 4줄 있는데 3칸이 비어 있어요. 물건이 든 사물함의 수를 곱셈구구로 구하고 방법을 설명해 보세요.","answer_guide":{"answer":"예: 사물함은 6 × 4 = 24칸이다. 3칸이 비었으므로 24 − 3 = 21칸에 물건이 들어 있다.","scoring_points":["곱셈구구로 나누어 곱하거나 빈자리를 채워 곱했는가","더하거나 빼는 과정을 바르게 썼는가","답을 바르게 구했는가"]},"explanation":["같은 수씩 놓인 덩이를 찾아 곱해요.","빈자리는 빼고, 덩이가 둘이면 두 곱을 더해요.","하나씩 세는 것보다 빠르고 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_math_u2_review_d#25','math',2,2,'u2','','g2_2_math_u2_review_d','unit_review','M2-2-u2-C8',4,'essay','teacher','곱셈표에서 곱이 36인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-2-u2-C8","difficulty":4,"kind":"essay","stem":"곱셈표에서 곱이 36인 곱셈구구를 모두 찾아 쓰고, 어떻게 찾았는지 설명해 보세요.","answer_guide":{"answer":"예: 4 × 9, 6 × 6, 9 × 4. 곱셈표에서 36이 있는 칸을 모두 찾았다. 6 × 6은 두 수가 같아 하나뿐이다.","scoring_points":["곱이 36인 곱셈구구를 하나 이상 찾았는가","두 수를 바꾼 것과 다른 단의 것까지 모두 찾았는가","곱셈표에서 36인 칸을 찾았다는 등 방법을 썼는가"]},"explanation":["곱셈표에서 같은 수가 있는 칸을 모두 찾아요.","두 수를 바꾸어 곱해도 곱이 같아요.","곱이 같은 곱셈구구는 여러 개일 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
